14	package io.reactivex.rxjava4.internal.operators.streamable;
15	
16	import java.io.Serial;
17	import java.util.Collection;
18	import java.util.concurrent.*;
19	import java.util.concurrent.atomic.*;
20	import java.util.function.*;
21	
22	import io.reactivex.rxjava4.annotations.*;
23	import io.reactivex.rxjava4.core.*;
24	import io.reactivex.rxjava4.core.config.StreamableInterceptConfig;
25	import io.reactivex.rxjava4.disposables.Disposable;
26	import io.reactivex.rxjava4.exceptions.*;
27	import io.reactivex.rxjava4.functions.Consumer;
28	import io.reactivex.rxjava4.internal.util.*;
29	
30	/**
31	 * Helper static methods for {@link Streamable}s, {@link CompletableFuture}s and {@link CompletionStage}s.
32	 * @since 4.0.0
33	 */
34	public enum StreamableHelper {
35	    ;
36	
37	    /**
38	     * Checks which source completes first, calls the given acceptor with 1 or 2 indicating the winner,
39	     * then terminates the resulting {@link CompletableFuture} with said terminal event.
40	     * <p>
41	     * Use the {@code thenAcceptor} to do something about the winner and/or loser before the terminal
42	     * signal is propagated further.
43	     * @param <T> the common element type of the stages
44	     * @param first the first stage to wait for
45	     * @param second the second stage to wait for
46	     * @param thenAcceptor the callback that receives who won
47	     * @return the new {@code CompletableFuture} that gets completed with the winner's event.
48	     */
49	    @CheckReturnValue
50	    @NonNull
51	    public static <T> CompletableFuture<T> race(CompletionStage<T> first, CompletionStage<T> second, IntConsumer thenAcceptor) {
52	        var result = new CompletableFuture<T>();
53	        var winner = new AtomicInteger();
54	        armRace(first, 1, winner, thenAcceptor, result);
55	        armRace(second, 2, winner, thenAcceptor, result);
56	        return result;
57	    }
58	
59	    /**
60	     * Arms one side of a {@link #race}: when {@code stage} completes first (wins the {@code winner}
61	     * race under the given {@code id}), notifies the acceptor and relays the terminal event to {@code result}.
62	     */
63	    private static <T> void armRace(CompletionStage<T> stage, int id, AtomicInteger winner,
64	            IntConsumer thenAcceptor, CompletableFuture<T> result) {
65	        stage.whenComplete((v, e) -> {
66	            if (winner.compareAndSet(0, id)) {
67	                thenAcceptor.accept(id);
68	                if (e != null) {
69	                    result.completeExceptionally(e);
70	                } else {
71	                    result.complete(v);
72	                }
73	            }
74	        });
75	    }
76	
77	    /**
78	     * Checks which source completes first, calls the given acceptor with 1 or 2 indicating the winner.
79	     * <p>
80	     * Use the {@code thenAcceptor} to do something about the winner and/or loser.
81	     * @param <T> the common element type of the stages
82	     * @param first the first stage to wait for
83	     * @param second the second stage to wait for
84	     * @param thenAcceptor the callback that receives who won
85	     */
86	    public static <T> void whenEither(CompletionStage<T> first, CompletionStage<T> second, IntConsumer thenAcceptor) {
87	        var winner = new AtomicInteger();
88	        first.whenComplete((_, _) -> {
89	            if (winner.compareAndSet(0, 1)) {
90	                thenAcceptor.accept(1);
91	            }
92	        });
93	        second.whenComplete((_, _) -> {
94	            if (winner.compareAndSet(0, 2)) {
95	                thenAcceptor.accept(2);
96	            }
97	        });
98	    }
99	
100	    /**
101	     * Creates a {@link CompletableFuture} that completes when both sources complete in a way,
102	     * relaying one or the other's exception, or both exceptions via {@link CompositeException}.
103	     * @param one a stage to wait for completion
104	     * @param two a stage to wait for completion
105	     * @return then new {@code CompletableFuture} instance
106	     */
107	    @CheckReturnValue
108	    @NonNull
109	    public static CompletableFuture<Void> whenBoth(CompletionStage<?> one, CompletionStage<?> two) {
110	        var result = new CompletableFuture<Void>();
111	        var errors = new AtomicThrowable();
112	        var wip = new AtomicInteger(2);
113	        BiConsumer<Object, Throwable> handler = (_, e) -> {
114	            if (e != null) {
115	                errors.tryAddThrowableOrReport(e);
116	            }
117	            if (wip.decrementAndGet() == 0) {
118	                var err = errors.get();
119	                if (err != null) {
120	                    result.completeExceptionally(err);
121	                } else {
122	                    result.complete(null);
123	                }
124	            }
125	        };
126	        one.whenComplete(handler);
127	        two.whenComplete(handler);
128	        return result;
129	    }
130	
131	    /**
132	     * Creates a {@link CompletableFuture} that completes when the second completes after the first completes,
133	     * chaining their completion into a sequence and relays either or both's exception as is or via a
134	     * {@link CompositeException}.
135	     * @param first the first stage to wait for completion
136	     * @param supplier produces the next stage when the first stage completes in any way
137	     * @return the new {@code CompletableFuture} instance
138	     */
139	    @CheckReturnValue
140	    @NonNull
141	    public static CompletableFuture<Void> andThenSupply(@NonNull CompletionStage<?> first,
142	            @NonNull Supplier<@NonNull ? extends CompletionStage<?>> supplier) {
143	        var result = new CompletableFuture<Void>();
144	        var errors = new AtomicThrowable();
145	        first.whenComplete((_, e) -> {
146	            if (e != null) {
147	                errors.tryAddThrowableOrReport(e);
148	            }
149	            supplier.get().whenComplete((_, e1) -> {
150	                if (e1 != null) {
151	                    errors.tryAddThrowableOrReport(e1);
152	                }
153	                var err = errors.get();
154	                if (err != null) {
155	                    result.completeExceptionally(err);
156	                } else {
157	                    result.complete(null);
158	                }
159	            });
160	        });
161	        return result;
162	    }
163	
164	    /**
165	     * Check if the throwable is itself a {@link CancellationException} or
166	     * it is a {@link CompletionException} caused by a {@code CancellationException}.
167	     * <p>
168	     * Why is that {@code completableFuture.completeExceptionally(new CancellationException())}
169	     * results in the wrapping? no idea.
170	     * @param e the throwable to check
171	     * @return true if the throwable holds a cancellation exception in some fashion
172	     */
173	    @CheckReturnValue
174	    static boolean isCancellation(@Nullable Throwable e) {
175	        return e instanceof CancellationException
176	                || (e instanceof CompletionException && e.getCause() instanceof CancellationException);
177	    }
178	
179	    /**
180	     * Creates a {@link CompletableFuture} that relays the terminal events of the source {@code stage}
181	     * except any {@link CancellationException} if the given {@link Disposable#isDisposed()} returns {@code true}.
182	     * <p>
183	     * Use it to suppress expected cancellation errors.
184	     * @param <T> the element type of the stage
185	     * @param stage the original stage to gate the cancellation exception of
186	     * @param disposable the {@code Disposable} to check
187	     * @param defaultValue to signal if the cancellation exception was gated
188	     * @return the new {@code CompletableFuture} instance
189	     */
190	    @CheckReturnValue
191	    @NonNull
192	    public static <T> CompletableFuture<T> suppressCancel(
193	            @NonNull CompletionStage<T> stage, @NonNull Disposable disposable, T defaultValue) {
194	        var result = new CompletableFuture<T>();
195	        stage.whenComplete((v, e) -> {
196	            if (disposable.isDisposed() && isCancellation(e)) {
197	                result.complete(defaultValue);
198	            } else
199	            if (e != null) {
200	                result.completeExceptionally(e);
201	            } else {
202	                result.complete(v);
203	            }
204	        });
205	        return result;
206	    }
207	
208	    /**
209	     * Creates a {@link CompletableFuture} that suppresses the source value or cancellation exception and
210	     * replaces them with a normal completion signaling the {@code defaultValue}.
211	     * <p>
212	     * Use it to suppress expected cancellation errors and any source value.
213	     * @param <T> the element type of the stage
214	     * @param stage the original stage to gate the cancellation exception of
215	     * @param defaultValue to signal if the cancellation exception was gated
216	     * @return the new {@code CompletableFuture} instance
217	     */
218	    @CheckReturnValue
219	    @NonNull
220	    public static <T> CompletableFuture<T> suppressValueAndCancel(
221	            @NonNull CompletionStage<T> stage, T defaultValue) {
222	        var result = new CompletableFuture<T>();
223	        stage.whenComplete((_, e) -> {
224	            if (isCancellation(e)) { // FIXME coverage possible even?
225	                result.complete(defaultValue);
226	            } else
227	            if (e != null) {
228	                result.completeExceptionally(e);
229	            } else {
230	                result.complete(defaultValue);
231	            }
232	        });
233	        return result;
234	    }
235	
236	    /**
237	     * When the stage completes, the future is completed with the very same value or exception.
238	     * @param <T> the element type
239	     * @param stage the stage to forward its completion signals
240	     * @param future the future to receive the completion signals
241	     */
242	    public static <T> void forward(CompletionStage<T> stage, CompletableFuture<T> future) {
243	        stage.whenComplete((u, e) -> {
244	            if (e != null) {
245	                future.completeExceptionally(e);
246	            } else {
247	                future.complete(u);
248	            }
249	        });
250	    }
251	
252	    /**
253	     * Awaits all the stages to complete in any form, then completes the returned {@link CompletableFuture} normally,
254	     * or via the possible {@link CompositeException}s of all the failed stages.
255	     * @param stages the collection of {@link CompletionStage}s to await
256	     * @return the new {@code CompletableFuture} that gets completed
257	     */
258	    public static CompletableFuture<Void> awaitAllVoid(Collection<? extends CompletionStage<?>> stages) {
259	        int size = stages.size();
260	        if (size == 0) {
261	            return Streamer.FINISHED;
262	        }
263	        var cf = new CompletableFuture<Void>();
264	        var wip = new AtomicIntegerCompleter(cf, size);
265	
266	        for (var stage : stages) {
267	            stage.whenComplete(wip);
268	        }
269	
270	        return cf;
271	    }
272	
273	    public static CompletableFuture<Boolean> awaitAllBoolean(Collection<? extends CompletionStage<Boolean>> stages) {
274	        int size = stages.size();
275	        if (size == 0) {
276	            return Streamer.NEXT_FALSE;
277	        }
278	        var cf = new CompletableFuture<Boolean>();
279	        var wip = new AtomicIntegerBooleanCompleter(cf, size);
280	
281	        for (var stage : stages) {
282	            stage.whenComplete(wip);
283	        }
284	
285	        return cf;
286	    }
287	
288	    /**
289	     * A counter and callback composite to save on allocation cost for awaiting many stages via
290	     * {@link #awaitAllVoid}.
291	     */
292	    static final class AtomicIntegerCompleter extends AtomicInteger implements BiConsumer<Object, Throwable> {
293	
294	        @Serial
295	        private static final long serialVersionUID = 1598649149973711008L;
296	
297	        final CompletableFuture<Void> future;
298	
299	        final AtomicThrowable errors;
300	
301	        public AtomicIntegerCompleter(CompletableFuture<Void> future, int count) {
302	            super(count);
303	            this.future = future;
304	            this.errors = new AtomicThrowable();
305	        }
306	
307	        @Override
308	        public void accept(Object t, Throwable u) {
309	            if (u != null && !isCancellation(u)) {
310	                errors.tryAddThrowable(ExceptionHelper.unwrap(u));
311	            }
312	            if (decrementAndGet() == 0) {
313	                var err = errors.terminate();
314	                if (err != null) {
315	                    future.completeExceptionally(err);
316	                } else {
317	                    future.complete(null);
318	                }
319	            }
320	        }
321	    }
322	    /**
323	     * A counter and callback composite to save on allocation cost for awaiting many stages via
324	     * {@link #awaitAllBoolean}.
325	     */
326	    static final class AtomicIntegerBooleanCompleter extends AtomicInteger implements BiConsumer<Boolean, Throwable> {
327	
328	        @Serial
329	        private static final long serialVersionUID = 1598649149973711008L;
330	
331	        final CompletableFuture<Boolean> future;
332	
333	        final AtomicThrowable errors;
334	
335	        final AtomicBoolean outcome;
336	
337	        public AtomicIntegerBooleanCompleter(CompletableFuture<Boolean> future, int count) {
338	            super(count);
339	            this.future = future;
340	            this.errors = new AtomicThrowable();
341	            this.outcome = new AtomicBoolean(true);
342	        }
343	
344	        @Override
345	        public void accept(Boolean t, Throwable u) {
346	            if (u != null && !isCancellation(u)) {
347	                errors.tryAddThrowable(ExceptionHelper.unwrap(u));
348	            }
349	            if (t != null && !t) {
350	                outcome.set(false);
351	            }
352	            if (decrementAndGet() == 0) {
353	                var err = errors.terminate();
354	                if (err != null) {
355	                    future.completeExceptionally(err);
356	                } else {
357	                    future.complete(outcome.get());
358	                }
359	            }
360	        }
361	    }
362	
363	    /**
364	     * Create a {@link StreamableInterceptConfig} that can consume the {@link Streamer#next()} errors.
365	     * @param <T> the element type of the {@link Streamable}
366	     * @param consumer the consumer to be called with the error
367	     * @return the new {@code StreamableInterceptConfig} instance
368	     */
369	    public static <T> StreamableInterceptConfig<T> createOnError(Consumer<? super Throwable> consumer) {
370	        return new StreamableInterceptConfig<>((_, v) -> v, (_, v) -> {
371	            var cf = new CompletableFuture<Boolean>();
372	            v.whenComplete((u, e) -> {
373	                if (e != null) {
374	                    try {
375	                        consumer.accept(e);
376	                    } catch (Throwable ex) {
377	                        Exceptions.throwIfFatal(ex);
378	                        ex.addSuppressed(e);
379	                        e = ex;
380	                    }
381	                    cf.completeExceptionally(e);
382	                } else {
383	                    cf.complete(u);
384	                }
385	            });
386	            return cf;
387	        }, v -> v, (_, v) -> v);
388	    }
389	
390	    /**
391	     * Shortcuts the stage to call the consumer directly if it is detected as completed.
392	     * @param <T> the signal type of the {@link CompletionStage}
393	     * @param stage the stage to handle
394	     * @param consumer the consumer called with the stage's value or its exception
395	     */
396	    public static <T> void whenComplete(CompletionStage<T> stage, java.util.function.BiConsumer<? super T, ? super Throwable> consumer) {
397	        var cf = stage.toCompletableFuture();
398	        switch (cf.state()) {
399	        case SUCCESS -> consumer.accept(cf.getNow(null), null);
400	        case CANCELLED, FAILED -> consumer.accept(null, cf.exceptionNow());
401	        default -> stage.whenComplete(consumer);
402	        }
403	    }
404	}
