23	public record StreamableFromArray<T>(@NonNull T[] items) implements Streamable<T> {
24	
25	    @Override
26	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
27	        return new FromArrayStreamer<>(items);
28	    }
29	
30	    static final class FromArrayStreamer<T>
31	    implements Streamer<T>, IndexableSource<T>, EnumerableSource<T> {
32	
33	        final T[] items;
34	
35	        int index;
36	
37	        public FromArrayStreamer(T[] items) {
38	            this.items = items;
39	            this.index = -1;
40	        }
41	
42	        @Override
43	        public @NonNull CompletionStage<Boolean> next() {
44	            if (++index >= items.length) {
45	                return NEXT_FALSE;
46	            }
47	            if (current() == null) {
48	                return CompletableFuture.failedFuture(createNullError(index));
49	            }
50	            return NEXT_TRUE;
51	        }
52	
53	        static NullPointerException createNullError(int index) {
54	            return new NullPointerException("Item at index " + index + " is null.");
55	        }
56	
57	        @Override
58	        public boolean nextSync() {
59	            if (++index < items.length) {
60	                if (current() == null) {
61	                    throw createNullError(index);
62	                }
63	                return true;
64	            };
65	            return false;
66	        }
67	
68	        @Override
69	        public @NonNull T current() {
70	            return items[index];
71	        }
72	
73	        @Override
74	        public @NonNull CompletionStage<Void> finish() {
75	            index = items.length;
76	            return FINISHED;
77	        }
78	
79	        @Override
80	        public @NonNull T elementAt(long index) throws Throwable {
81	            var v = items[(int)index];
82	            if (v ==  null) {
83	                throw createNullError((int)index);
84	            }
85	            return v;
86	        }
87	
88	        @Override
89	        public long limit() {
90	            return items.length;
91	        }
92	    }
93	}
