14	package io.reactivex.rxjava4.internal.operators.streamable;
15	
16	import java.util.*;
17	import java.util.concurrent.*;
18	
19	import io.reactivex.rxjava4.annotations.NonNull;
20	import io.reactivex.rxjava4.core.*;
21	import io.reactivex.rxjava4.disposables.StreamerCancellation;
22	import io.reactivex.rxjava4.exceptions.Exceptions;
23	import io.reactivex.rxjava4.internal.operators.streamable.StreamableEmpty.EmptyStreamer;
24	import io.reactivex.rxjava4.operators.EnumerableSource;
25	
26	public record StreamableFromIterable<T>(@NonNull Iterable<? extends T> items) implements Streamable<T> {
27	
28	    @SuppressWarnings("unchecked")
29	    @Override
30	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
31	        Iterator<? extends T> iterator;
32	        try {
33	            iterator = Objects.requireNonNull(items.iterator(), "iterator is null");
34	            if (!iterator.hasNext()) {
35	                return (Streamer<T>)EmptyStreamer.INSTANCE;
36	            }
37	        } catch (Throwable ex) {
38	            Exceptions.throwIfFatal(ex);
39	            return StreamableError.createFailed(ex);
40	        }
41	        return new IteratorStreamer<>(iterator, null);
42	    }
43	
44	    static final class IteratorStreamer<T> implements Streamer<T>, EnumerableSource<T> {
45	
46	        Iterator<? extends T> iterator;
47	
48	        AutoCloseable toClose;
49	
50	        long index;
51	
52	        T current;
53	
54	        IteratorStreamer(Iterator<? extends T> iterator, AutoCloseable toClose) {
55	            this.iterator = iterator;
56	            this.toClose = toClose;
57	        }
58	
59	        @Override
60	        public @NonNull CompletionStage<Boolean> next() {
61	            if (index == 0L || iterator.hasNext()) {
62	                var v = iterator.next();
63	                current = v;
64	                if (v == null) {
65	                    return CompletableFuture.failedStage(createNullError(index));
66	                }
67	                index++;
68	                return NEXT_TRUE;
69	            }
70	            current = null;
71	            return NEXT_FALSE;
72	        }
73	
74	        static NullPointerException createNullError(long index) {
75	            return new NullPointerException("Item at index " + index + " is null.");
76	        }
77	
78	        @Override
79	        public @NonNull T current() {
80	            return current;
81	        }
82	
83	        @Override
84	        public @NonNull CompletionStage<Void> finish() {
85	            iterator = null;
86	            current = null;
87	            var toClose = this.toClose;
88	            this.toClose = null;
89	            if (toClose != null) {
90	                try {
91	                    toClose.close();
92	                } catch (Throwable ex) {
93	                    Exceptions.throwIfFatal(ex);
94	                    return CompletableFuture.failedFuture(ex);
95	                }
96	            }
97	            return FINISHED;
98	        }
99	
100	        @Override
101	        public boolean nextSync() throws Throwable {
102	            if (index == 0L || iterator.hasNext()) {
103	                var v = iterator.next();
104	                current = v;
105	                if (v == null) {
106	                    throw createNullError(index);
107	                }
108	                index++;
109	                return true;
110	            }
111	            current = null;
112	            return false;
113	        }
114	    }
115	}
