25	public record StreamableFromStream<T>(@NonNull Stream<? extends T> items) implements Streamable<T> {
26	
27	    @SuppressWarnings("unchecked")
28	    @Override
29	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
30	        Iterator<? extends T> iterator;
31	        boolean hasNext;
32	        try {
33	            iterator = Objects.requireNonNull(items.iterator(), "iterator is null");
34	            hasNext = iterator.hasNext();
35	        } catch (Throwable ex) {
36	            Exceptions.throwIfFatal(ex);
37	            try {
38	                items.close();
39	            } catch (Throwable exc) {
40	                Exceptions.throwIfFatal(exc);
41	                ex.addSuppressed(exc);
42	            }
43	            return StreamableError.createFailed(ex);
44	        }
45	        if (!hasNext) {
46	            try {
47	                items.close();
48	            } catch (Throwable ex) {
49	                Exceptions.throwIfFatal(ex);
50	                return StreamableError.createFailed(ex);
51	            }
52	
53	            return (Streamer<T>)EmptyStreamer.INSTANCE;
54	        }
55	        return new StreamableFromIterable.IteratorStreamer<>(iterator, items);
56	    }
57	}
