50	    static abstract class MapStreamerBase<T, R> implements Streamer<R>, java.util.function.Function<Boolean, Boolean> {
51	
52	        final Streamer<T> upstream;
53	
54	        final Function<? super T, ? extends R> mapper;
55	
56	        R current;
57	
58	        MapStreamerBase(Streamer<T> upstream, Function<? super T, ? extends R> mapper) {
59	            this.upstream = upstream;
60	            this.mapper = mapper;
61	        }
62	
63	        @Override
64	        public @NonNull CompletionStage<Boolean> next() {
65	            var stage = upstream.next();
66	            if (stage instanceof CompletableFuture<Boolean> cf) {
67	                if (cf.state() == State.SUCCESS) {
68	                    if (cf.getNow(false)) {
69	                        try {
70	                            current = Objects.requireNonNull(mapper.apply(upstream.current()), "The mapper returned a null value");
71	                        } catch (Throwable ex) {
72	                            Exceptions.throwIfFatal(ex);
73	                            return CompletableFuture.failedFuture(ex);
74	                        }
75	                        return NEXT_TRUE;
76	                    }
77	                    return NEXT_FALSE;
78	                }
79	            }
80	
81	            return stage.thenApply(this);
82	        }
83	
84	        @Override
85	        public Boolean apply(Boolean e) {
86	            if (e) {
87	                try {
88	                    current = Objects.requireNonNull(mapper.apply(upstream.current()), "The mapper returned a null value");
89	                } catch (Throwable ex) {
90	                    Exceptions.throwIfFatal(ex);
91	                    throw ExceptionHelper.wrapOrThrow(ex);
92	                }
93	                return true;
94	            }
95	            return false;
96	        }
