49	    static abstract class MapOptionalStreamer<T, R> extends AtomicInteger
50	    implements Streamer<R>, BiConsumer<Boolean, Throwable> {
51	
52	        @Serial
53	        private static final long serialVersionUID = 6360266262761297472L;
54	
55	        final Streamer<T> upstream;
56	
57	        final Function<? super T, ? extends Optional<? extends R>> mapper;
58	
59	        R current;
60	
61	        CompletableFuture<Boolean> nextReady;
62	
63	        MapOptionalStreamer(Streamer<T> upstream, Function<? super T, ? extends Optional<? extends R>> mapper) {
64	            this.upstream = upstream;
65	            this.mapper = mapper;
66	        }
67	
68	        @Override
69	        public @NonNull CompletionStage<Boolean> next() {
70	            nextReady = new CompletableFuture<>();
71	            drain();
72	            return nextReady;
73	        }
74	
75	        void drain() {
76	            for (;;) {
77	                var upstreamNext = upstream.next().toCompletableFuture();
78	                var state = upstreamNext.state();
79	
80	                if (state == State.RUNNING) {
81	                    set(1);
82	                    upstreamNext.whenComplete(this);
83	                    if (compareAndSet(1, 0)) {
84	                        return;
85	                    }
86	                    state = upstreamNext.state();
87	                }
88	                if (state == State.SUCCESS) {
89	                    if (upstreamNext.getNow(false)) {
90	                        boolean pass;
91	                        T value = upstream.current();
92	                        Optional<? extends R> result = null;
93	                        try {
94	                            result = Objects.requireNonNull(mapper.apply(value), "The mapper returned a null item");
95	                        } catch (Throwable ex) {
96	                            Exceptions.throwIfFatal(ex);
97	                            nextReady.completeExceptionally(ex);
98	                            return;
99	                        }
100	                        pass = result.isEmpty();
101	                        if (!pass) {
102	                            current = result.get();
103	                            nextReady.complete(true);
104	                            return;
105	                        }
106	                    } else {
107	                        nextReady.complete(false);
108	                        return;
109	                    }
110	                } else {
111	                    nextReady.completeExceptionally(upstreamNext.exceptionNow());
112	                    return;
113	                }
114	            }
115	        }
116	
117	        @Override
118	        public void accept(Boolean t, Throwable u) {
119	            if (!compareAndSet(1, 2)) {
120	                if (u != null) {
121	                    nextReady.completeExceptionally(u);
122	                } else
123	                if (t) {
124	                    boolean pass;
125	                    T value = upstream.current();
126	                    Optional<? extends R> result = null;
127	                    try {
128	                        result = Objects.requireNonNull(mapper.apply(value), "The mapper returned a null item");
129	                    } catch (Throwable ex) {
130	                        Exceptions.throwIfFatal(ex);
131	                        nextReady.completeExceptionally(ex);
132	                        return;
133	                    }
134	                    pass = result.isEmpty();
135	                    if (!pass) {
136	                        current = result.get();
137	                        nextReady.complete(true);
138	                        return;
139	                    }
140	                    drain();
141	                } else {
142	                    nextReady.complete(false);
143	                }
144	            }
145	        }
146	
147	        @Override
148	        public @NonNull R current() {
149	            return current;
150	        }
151	
152	        @Override
153	        public @NonNull CompletionStage<Void> finish() {
154	            current = null;
155	            return upstream.finish();
156	        }
157	    }
