67	            this.upstream = upstream;
68	            this.cancellation = cancellation;
69	            this.predicate = predicate;
70	        }
71	
72	        @Override
73	        public @NonNull CompletionStage<Boolean> next() {
74	            nextReady = new CompletableFuture<Boolean>();
75	            drain();
76	            return nextReady;
