92	            for (;;) {
93	                var upstreamNext = upstream.next().toCompletableFuture();
94	
95	                var state = upstreamNext.state();
96	                if (state == State.RUNNING) {
97	                    set(1);
98	                    upstreamNext.whenComplete(this);
