104	
105	                if (state == State.SUCCESS) {
106	                    boolean has = upstreamNext.getNow(false);
107	                    if (!has) {
108	                        nextReady.complete(false);
109	                        return;
110	                    }
111	                    T value = upstream.current();
112	                    boolean pass;
113	                    try {
114	                        pass = predicate.test(value);
115	                    } catch (Throwable ex) {
116	                        Exceptions.throwIfFatal(ex);
117	                        nextReady.completeExceptionally(ex);
118	                        return;
119	                    }
120	                    if (pass) {
121	                        current = value;
122	                        nextReady.complete(true);
123	                        return;
124	                    }
125	                } else {
