146	                            return;
147	                        }
148	                        if (pass) {
149	                            current = value;
150	                            nextReady.complete(true);
151	                        } else {
152	                            drain();
153	                        }
154	                    } else {
155	                        nextReady.complete(false);
156	                    }
157	                }
158	            }
159	        }
