24	import io.reactivex.rxjava4.internal.subscriptions.SubscriptionHelper;
25	import io.reactivex.rxjava4.internal.util.ExceptionHelper;
26	import io.reactivex.rxjava4.internal.virtual.VirtualResumable;
27	
28	public record StreamableFromPublisher<T>(@NonNull Publisher<T> source,
29	        @Nullable Executor executor)
30	implements Streamable<T>, HasUpstreamPublisher<T> {
31	
32	    @Override
33	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
34	
35	        var flow = Flowable.fromPublisher(source);
36	        var streamer = new FlowableStreamer<T>(
37	                new AtomicReference<>(),
38	                new AtomicLong(),
39	                new AtomicReference<>(),
40	                new AtomicReference<>(),
41	                new VirtualResumable(),
42	                executor,
43	                cancellation
44	                );
45	        cancellation.add(streamer);
46	        flow.subscribe(streamer);
47	        return streamer;
48	    }
49	
50	    record FlowableStreamer<T>(
51	            AtomicReference<Subscription> upstream,
52	            AtomicLong requester,
53	            AtomicReference<T> item,
54	            AtomicReference<Throwable> error,
55	            VirtualResumable resumer,
56	            Executor executor,
57	            StreamerCancellation cancellation)
58	    implements Flow.Subscriber<T>, Streamer<T>, Disposable, java.util.function.Supplier<Boolean>, Runnable {
59	
60	        @Override
61	        public void onSubscribe(Subscription subscription) {
62	            SubscriptionHelper.deferredSetOnce(upstream, requester, subscription);
63	        }
64	
65	        @Override
66	        public void onNext(T item) {
67	            this.item.set(item);
68	            resumer.resume();
69	        }
70	
71	        @Override
72	        public void onError(Throwable throwable) {
73	            error.set(throwable);
74	            upstream.set(SubscriptionHelper.CANCELLED);
75	            resumer.resume();
76	        }
77	
78	        @Override
79	        public void onComplete() {
80	            error.compareAndSet(null, ExceptionHelper.TERMINATED);
81	            upstream.set(SubscriptionHelper.CANCELLED);
82	            resumer.resume();
83	        }
84	
85	        @Override
86	        public void dispose() {
87	            if (SubscriptionHelper.cancel(upstream)) {
88	                resumer.resume();
89	            }
90	        }
91	
92	        @Override
93	        public boolean isDisposed() {
94	            return SubscriptionHelper.CANCELLED == upstream.get();
95	        }
96	
97	        @Override
98	        public @NonNull CompletionStage<Boolean> next() {
99	            return CompletableFuture.supplyAsync(this, executor);
100	        }
101	
102	        @Override
103	        public Boolean get() {
104	            item.lazySet(null);
105	            SubscriptionHelper.deferredRequest(upstream, requester, 1);
106	            if (!isDisposed()) {
107	                resumer.await();
108	            }
109	
110	            if (item.get() != null) {
111	                return true;
112	            }
113	            var err = error.get();
114	            if (err == ExceptionHelper.TERMINATED) {
115	                return false;
116	            }
117	            if (err == null && isDisposed()) {
118	                throw new CancellationException();
119	            }
120	            throw ExceptionHelper.wrapOrThrow(err);
121	        }
122	
123	        @Override
124	        public @NonNull T current() {
125	            return item.get();
126	        }
127	
128	        @Override
129	        public @NonNull CompletionStage<Void> finish() {
130	            return CompletableFuture.runAsync(this);
131	        }
132	
133	        @Override
134	        public void run() {
135	            item.lazySet(null);
136	            SubscriptionHelper.cancel(upstream);
137	            cancellation.delete(this);
138	        }
139	    }
140	}
