23	/**
24	 * Represents a reusable ping-pong style notification exchange where
25	 * one use/thread can signal {@link #ready()} to wake up another use/thread
26	 * on a {@link #await()} call.
27	 * @param <T> the element type of the notification pass-around
28	 * @since 4.0.0
29	 */
30	public final class StageResumable<T> extends AtomicReference<CompletableFuture<T>>
31	implements BiConsumer<T, Throwable> {
32	
33	    @Serial
34	    private static final long serialVersionUID = -7518852864146380895L;
35	
36	    /**
37	     * When the producer has arranged the item transfer via some field or queue,
38	     * call this method and call {@link CompletableFuture#complete(Object)}
39	     * or {@link CompletableFuture#completeExceptionally(Throwable)} to
40	     * signal resumption for any current or upcoming {@link #await()} caller.
41	     * @return the {@code CompletableFuture} to complete in some way
42	     */
43	    @CheckReturnValue
44	    @NonNull
45	    public CompletableFuture<T> ready() {
46	        CompletableFuture<T> cf;
47	        for (;;) {
48	            cf = get();
49	            if (cf !=  null) {
50	                break;
51	            }
52	            cf = new CompletableFuture<>();
53	            if (compareAndSet(null, cf)) {
54	                break;
55	            }
56	        }
57	        return cf;
58	    }
59	
60	    /**
61	     * When the consumer is ready to receive an item, call this method
62	     * and apply a continuation function, such as {@link CompletableFuture#whenComplete(BiConsumer)}
63	     * to it to handle the signal and process any external data made ready.
64	     * @return the {@code CompletableFuture} to observe a completion value or exception
65	     */
66	    @CheckReturnValue
67	    @NonNull
68	    public CompletableFuture<T> await() {
69	        CompletableFuture<T> cf;
70	        for (;;) {
71	            cf = get();
72	            if (cf != null) {
73	                break;
74	            }
75	            cf = new CompletableFuture<>();
76	            if (compareAndSet(null, cf)) {
77	                break;
78	            }
79	        }
80	        return cf.whenComplete(this);
81	    }
82	
83	    /// Used to clear any waiting [CompletableFuture] when the await finishes
84	    /// no concern to users and should not be called.
85	    /// @param t the completion value if any, ignored
86	    /// @param u the exception if any, ignored
87	    @Override
88	    public void accept(T t, Throwable u) {
89	        set(null);
90	    }
91	}
