27	public record StreamableSkip<T>(Streamable<T> source, long count) implements Streamable<T> {
28	
29	    @SuppressWarnings("unchecked")
30	    @Override
31	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
32	        var upstream = source.stream(cancellation);
33	        if (upstream instanceof IndexableSource<?> isrc) {
34	            return new SkipStreamerIndexed<>(upstream, (IndexableSource<T>)isrc, count);
35	        } else
36	        if (upstream instanceof DeferredEnumerableSource<?> dsrc) {
37	            return new SkipStreamerDeferredEnumerable<>(upstream, (DeferredEnumerableSource<T>)dsrc, count);
38	        } else
39	        if (upstream instanceof EnumerableSource<?> esrc) {
40	            return new SkipStreamerEnumerable<>(upstream, (EnumerableSource<T>)esrc, count);
41	        }
42	        return new SkipStreamerBasic<>(upstream, count);
43	    }
44	
45	    static abstract class SkipStreamer<T> extends AtomicInteger implements Streamer<T>, BiConsumer<Boolean, Throwable> {
46	
47	        @Serial
48	        private static final long serialVersionUID = 1988154737845167665L;
49	
50	        final Streamer<T> upstream;
51	
52	        long remaining;
53	
54	        CompletableFuture<Boolean> waiter;
55	
56	        SkipStreamer(Streamer<T> upstream, long count) {
57	            this.upstream = upstream;
58	            this.remaining = count;
59	            this.waiter = new CompletableFuture<>();
60	        }
61	
62	        @Override
63	        public @NonNull CompletionStage<Boolean> next() {
64	            if (remaining <= 0) {
65	                return upstream.next();
66	            }
67	            drain();
68	            return waiter;
69	        }
70	
71	        void drain() {
72	            for (;;) {
73	                var nextStage = upstream.next().toCompletableFuture();
74	                var state = nextStage.state();
75	                if (state == State.RUNNING) {
76	                    set(1);
77	                    nextStage.whenComplete(this);
78	                    if (compareAndSet(1, 0)) {
79	                        return;
80	                    }
81	                    state = nextStage.state();
82	                }
83	
84	                if (state == State.SUCCESS) {
85	                    if (nextStage.getNow(false)) {
86	                        if (remaining-- <= 0) {
87	                            waiter.complete(true);
88	                            return;
89	                        }
90	                        // still skipping, try the next upstream value
91	                    } else {
92	                        waiter.complete(false);
93	                        return;
94	                    }
95	                } else {
96	                    waiter.completeExceptionally(nextStage.exceptionNow());
97	                    return;
98	                }
99	            }
100	        }
101	
102	        @Override
103	        public void accept(Boolean t, Throwable u) {
104	            if (!compareAndSet(1, 2)) {
105	                if (u != null) {
106	                    waiter.completeExceptionally(u);
107	                } else {
108	                    if (t) {
109	                        if (remaining-- <= 0) {
110	                            waiter.complete(true);
111	                        } else {
112	                            drain();
113	                        }
114	                    } else {
115	                        waiter.complete(false);
116	                    }
117	                }
118	            }
119	        }
120	
121	        @Override
122	        public @NonNull T current() {
123	            return upstream.current();
124	        }
125	
126	        @Override
127	        public @NonNull CompletionStage<Void> finish() {
128	            return upstream.finish();
129	        }
130	    }
131	
132	    static final class SkipStreamerBasic<T> extends SkipStreamer<T> {
133	
134	        @Serial
135	        private static final long serialVersionUID = 7002195716600087893L;
136	
137	        SkipStreamerBasic(Streamer<T> upstream, long count) {
138	            super(upstream, count);
139	        }
140	    }
