142	    static final class SkipStreamerIndexed<T> extends SkipStreamer<T>
143	    implements IndexableSource<T> {
144	
145	        @Serial
146	        private static final long serialVersionUID = 773832461044750722L;
147	
148	        final IndexableSource<T> indexable;
149	
150	        final long count;
151	
152	        SkipStreamerIndexed(Streamer<T> upstream, IndexableSource<T> indexable, long count) {
153	            super(upstream, count);
154	            this.indexable = indexable;
155	            this.count = count;
156	        }
157	
158	        @Override
159	        public @NonNull T elementAt(long index) throws Throwable {
160	            return indexable.elementAt(index + count);
161	        }
162	
163	        @Override
164	        public long limit() {
165	            return Math.max(0, indexable.limit() - count);
166	        }
167	    }
168	
169	    static final class SkipStreamerEnumerable<T> extends SkipStreamer<T>
170	    implements EnumerableSource<T> {
171	
172	        @Serial
173	        private static final long serialVersionUID = 773832461044750722L;
174	
175	        final EnumerableSource<T> enumerable;
176	
177	        SkipStreamerEnumerable(Streamer<T> upstream, EnumerableSource<T> enumerable, long count) {
178	            super(upstream, count);
179	            this.enumerable = enumerable;
180	        }
181	
182	        @Override
183	        public boolean nextSync() throws Throwable {
184	            while (remaining-- > 0) {
185	                if (!enumerable.nextSync()) {
186	                    return false;
187	                }
188	            }
189	            return enumerable.nextSync();
190	        }
191	
192	    }
193	
194	    static final class SkipStreamerDeferredEnumerable<T> extends SkipStreamer<T>
195	    implements DeferredEnumerableSource<T> {
196	
197	        @Serial
198	        private static final long serialVersionUID = 773832461044750722L;
199	
200	        final DeferredEnumerableSource<T> enumerable;
201	
202	        SkipStreamerDeferredEnumerable(Streamer<T> upstream, DeferredEnumerableSource<T> enumerable, long count) {
203	            super(upstream, count);
204	            this.enumerable = enumerable;
205	        }
206	
207	        @Override
208	        public boolean nextSync() throws Throwable {
209	            while (remaining-- > 0) {
210	                if (!enumerable.nextSync()) {
211	                    return false;
212	                }
213	            }
214	            return enumerable.nextSync();
215	        }
216	
217	        @Override
218	        public CompletionStage<Boolean> enumerableReady() {
219	            return enumerable.enumerableReady();
220	        }
221	
222	    }
