15	
16	import java.util.concurrent.*;
17	import java.util.concurrent.atomic.AtomicInteger;
18	import java.util.function.BiConsumer;
19	
20	import io.reactivex.rxjava4.annotations.NonNull;
21	import io.reactivex.rxjava4.core.*;
22	import io.reactivex.rxjava4.disposables.*;
23	import io.reactivex.rxjava4.exceptions.Exceptions;
24	import io.reactivex.rxjava4.functions.Function;
25	import io.reactivex.rxjava4.internal.fuseable.HasUpstreamStreamableSource;
26	
27	public record StreamableRepeat<T>(
28	        Streamable<T> source,
29	        Function<? super Long, ? extends CompletionStage<Boolean>> whenFunction
30	)
31	implements Streamable<T>, HasUpstreamStreamableSource<T> {
32	
33	    @Override
34	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
35	        var streamer = new RepeatStreamer<>(source, cancellation, whenFunction);
36	        streamer.retrySource();
37	        return streamer;
38	    }
39	
40	    static final class RepeatStreamer<T>
41	    implements Streamer<T>, BiConsumer<Object, Throwable> {
42	
43	        final Streamable<T> source;
44	
45	        final StreamerCancellation downstreamCancellation;
46	
47	        final Function<? super Long, ? extends CompletionStage<Boolean>> whenFunction;
48	
49	        final AtomicInteger wipSource;
50	
51	        Streamer<T> currentStreamer;
52	
53	        CompletableFuture<Boolean> nextWaiter;
54	
55	        volatile int stage;
56	
57	        long completionCount;
58	
59	        Disposable whenFunctionCancel;
60	
61	        RepeatStreamer(Streamable<T> source, StreamerCancellation downstreamCancellation,
62	                Function<? super Long, ? extends CompletionStage<Boolean>> whenFunction) {
63	            this.source = source;
64	            this.downstreamCancellation = downstreamCancellation;
65	            this.whenFunction = whenFunction;
66	            this.wipSource = new AtomicInteger();
67	            this.stage = -1;
68	        }
69	
70	        void retrySource() {
71	            if (wipSource.getAndIncrement() != 0) {
72	                return;
73	            }
74	            do {
75	                // FIXME some operators don't clean up their StreamerCancellations so we hand out clean ones for now
76	                var innerCanceller = downstreamCancellation.derive();
77	                currentStreamer = source.stream(innerCanceller);
78	                if (stage == 0) {
79	                    stage = 1;
80	                    currentStreamer.next().whenComplete(this);
81	                }
82	            } while (wipSource.decrementAndGet() != 0);
83	        }
84	
85	        @Override
86	        public @NonNull CompletionStage<Boolean> next() {
87	            nextWaiter = new CompletableFuture<>();
88	            stage = 1;
89	            currentStreamer.next().whenComplete(this);
90	            return nextWaiter;
91	        }
92	
93	        @Override
94	        public void accept(Object t, Throwable u) {
95	            if (stage == 1) {
96	                if (u != null) {
97	                    nextWaiter.completeExceptionally(u);
98	                } else
99	                if ((Boolean)t) {
100	                    nextWaiter.complete(true);
101	                } else {
102	                    var streamer = currentStreamer;
103	                    currentStreamer = null;
104	                    stage = 2;
105	                    streamer.finish().whenComplete(this);
106	
107	                }
108	            } else
109	            if (stage == 2) {
110	                if (u != null) {
111	                    nextWaiter.completeExceptionally(u);
112	                } else {
113	                    try {
114	                        var cs = whenFunction.apply(completionCount++);
115	                        whenFunctionCancel = Disposable.fromAction(() -> cs.toCompletableFuture().cancel(true));
116	                        downstreamCancellation.add(whenFunctionCancel);
117	                        stage = 3;
118	                        cs.whenComplete(this);
119	                    } catch (Throwable ex) {
120	                        Exceptions.throwIfFatal(ex);
121	                        nextWaiter.completeExceptionally(ex);
122	                    }
123	                }
124	            } else { // stage 3
125	                downstreamCancellation.delete(whenFunctionCancel);
126	                whenFunctionCancel = null;
127	                var cf = nextWaiter;
128	                if (u != null) {
129	                    cf.completeExceptionally(u);
130	                } else
131	                if ((Boolean)t){
132	                    stage = 0;
133	                    retrySource();
134	                } else {
135	                    cf.complete(false);
136	                }
137	            }
138	        }
139	
140	        @Override
141	        public @NonNull T current() {
142	            return currentStreamer.current();
143	        }
144	
145	        @Override
146	        public @NonNull CompletionStage<Void> finish() {
147	            if (currentStreamer != null) {
148	                return currentStreamer.finish();
149	            }
150	            return FINISHED;
151	        }
152	    }
153	}
