22	import io.reactivex.rxjava4.disposables.*;
23	import io.reactivex.rxjava4.exceptions.Exceptions;
24	import io.reactivex.rxjava4.functions.BiFunction;
25	import io.reactivex.rxjava4.internal.fuseable.HasUpstreamStreamableSource;
26	
27	public record StreamableRetry<T>(
28	        Streamable<T> source,
29	        BiFunction<? super Long, ? super Throwable, ? extends CompletionStage<Boolean>> whenFunction
30	)
31	implements Streamable<T>, HasUpstreamStreamableSource<T> {
32	
33	    @Override
34	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
35	        var streamer = new RetryStreamer<>(source, cancellation, whenFunction);
36	        streamer.retrySource();
37	        return streamer;
38	    }
39	
40	    static final class RetryStreamer<T>
41	    implements Streamer<T>, BiConsumer<Object, Throwable> {
42	
43	        final Streamable<T> source;
44	
45	        final StreamerCancellation downstreamCancellation;
46	
47	        final BiFunction<? super Long, ? super Throwable, ? extends CompletionStage<Boolean>> whenFunction;
48	
49	        final AtomicInteger wipSource;
50	
51	        Streamer<T> currentStreamer;
52	
53	        CompletableFuture<Boolean> nextWaiter;
54	
55	        volatile int stage;
56	
57	        long failureCount;
58	
59	        Disposable whenFunctionCancel;
60	
61	        Throwable currentThrowable;
62	
63	        RetryStreamer(Streamable<T> source, StreamerCancellation downstreamCancellation,
64	                BiFunction<? super Long, ? super Throwable, ? extends CompletionStage<Boolean>> whenFunction) {
65	            this.source = source;
66	            this.downstreamCancellation = downstreamCancellation;
67	            this.whenFunction = whenFunction;
68	            this.wipSource = new AtomicInteger();
69	            this.stage = -1;
70	        }
71	
72	        void retrySource() {
73	            if (wipSource.getAndIncrement() != 0) {
74	                return;
75	            }
76	            do {
77	                // FIXME some operators don't clean up their StreamerCancellations so we hand out clean ones for now
78	                var innerCanceller = downstreamCancellation.derive();
79	                currentStreamer = source.stream(innerCanceller);
80	                if (stage == 0) {
81	                    stage = 1;
82	                    currentStreamer.next().whenComplete(this);
83	                }
84	            } while (wipSource.decrementAndGet() != 0);
85	        }
86	
87	        @Override
88	        public @NonNull CompletionStage<Boolean> next() {
89	            nextWaiter = new CompletableFuture<>();
90	            stage = 1;
91	            currentStreamer.next().whenComplete(this);
92	            return nextWaiter;
93	        }
94	
95	        @Override
96	        public void accept(Object t, Throwable u) {
97	            if (stage == 1) {
98	                if (u != null) {
99	                    currentThrowable = u;
100	                    var streamer = currentStreamer;
101	                    currentStreamer = null;
102	                    stage = 2;
103	                    streamer.finish().whenComplete(this);
104	                } else {
105	                    nextWaiter.complete((Boolean)t);
106	                }
107	            } else
108	            if (stage == 2) {
109	                if (u != null) {
110	                    u.addSuppressed(currentThrowable);
111	                } else {
112	                    u = currentThrowable;
113	                }
114	                currentThrowable = null;
115	                try {
116	                    var cs = whenFunction.apply(failureCount++, u);
117	                    whenFunctionCancel = Disposable.fromAction(() -> cs.toCompletableFuture().cancel(true));
118	                    downstreamCancellation.add(whenFunctionCancel);
119	                    stage = 3;
120	                    cs.whenComplete(this);
121	                } catch (Throwable ex) {
122	                    Exceptions.throwIfFatal(ex);
123	                    ex.addSuppressed(u);
124	                    nextWaiter.completeExceptionally(ex);
125	                }
126	            } else { // stage 3
127	                downstreamCancellation.delete(whenFunctionCancel);
128	                whenFunctionCancel = null;
129	                var cf = nextWaiter;
130	                if (u != null) {
131	                    cf.completeExceptionally(u);
132	                } else
133	                if ((Boolean)t){
134	                    stage = 0;
135	                    retrySource();
136	                } else {
137	                    cf.complete(false);
138	                }
139	            }
140	        }
141	
142	        @Override
143	        public @NonNull T current() {
144	            return currentStreamer.current();
145	        }
146	
147	        @Override
148	        public @NonNull CompletionStage<Void> finish() {
149	            if (currentStreamer != null) {
150	                return currentStreamer.finish();
151	            }
152	            return FINISHED;
153	        }
154	    }
155	}
