25	public record StreamableDelay<T>(
26	        Streamable<T> source,
27	        long delay, TimeUnit unit, Scheduler scheduler
28	) implements Streamable<T>, HasUpstreamStreamableSource<T> {
29	
30	    @Override
31	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
32	        var worker = scheduler.createWorker();
33	        cancellation.add(worker);
34	        return new DelayStreamer<>(source.stream(cancellation), delay, unit, worker, cancellation);
35	    }
