37	    static final class DelayStreamer<T> implements Streamer<T>, BiConsumer<Boolean, Throwable>, Runnable {
38	
39	        final Worker worker;
40	
41	        final Streamer<T> upstream;
42	
43	        final long delay;
44	
45	        final TimeUnit unit;
46	
47	        final StreamerCancellation cancellation;
48	
49	        CompletableFuture<Boolean> nextReady;
50	
51	        Disposable onDisposed;
52	
53	        DelayStreamer(Streamer<T> upstream, long delay, TimeUnit unit, Worker worker, StreamerCancellation cancellation) {
54	            this.upstream = upstream;
55	            this.delay = delay;
56	            this.unit = unit;
57	            this.worker = worker;
58	            this.cancellation = cancellation;
59	        }
60	
61	        @Override
62	        public @NonNull CompletionStage<Boolean> next() {
63	            nextReady = new CompletableFuture<Boolean>();
64	            onDisposed = Disposable.fromFuture(nextReady, true);
65	            cancellation.add(onDisposed);
66	            upstream.next().whenComplete(this);
67	            return nextReady;
68	        }
69	
70	        @Override
71	        public void accept(Boolean t, Throwable u) {
72	            if (u != null) {
73	                cancellation.delete(onDisposed);
74	                nextReady.completeExceptionally(u);
75	            } else {
76	                if (t) {
77	                    worker.schedule(this, delay, unit);
78	                } else {
79	                    cancellation.delete(onDisposed);
80	                    nextReady.complete(false);
81	                }
82	            }
83	        }
84	
85	        @Override
86	        public void run() {
87	            cancellation.delete(onDisposed);
88	            nextReady.complete(true);
89	        }
90	
91	        @Override
92	        public @NonNull T current() {
93	            return upstream.current();
94	        }
95	
96	        @Override
97	        public @NonNull CompletionStage<Void> finish() {
98	            cancellation.delete(worker);
99	            nextReady = null;
100	            onDisposed = null;
101	            return FINISHED;
102	        }
103	    }
