35	    static final class IgnoreElementsStreamer<T> extends AtomicInteger
36	    implements Streamer<T>, BiConsumer<Object, Throwable> {
37	
38	        @Serial
39	        private static final long serialVersionUID = 2265801211815192189L;
40	
41	        final Streamer<T> upstream;
42	
43	        final CompletableFuture<Boolean> waiter;
44	
45	        int stage;
46	
47	        Throwable mainError;
48	
49	        volatile boolean done;
50	
51	        IgnoreElementsStreamer(Streamer<T> upstream)  {
52	            this.upstream = upstream;
53	            this.waiter = new CompletableFuture<>();
54	        }
55	
56	        @Override
57	        public @NonNull CompletionStage<Boolean> next() {
58	            if (stage == 0) {
59	                stage = 1;
60	                drain();
61	                return waiter;
62	            }
63	            return NEXT_FALSE;
64	        }
65	
66	        void drain() {
67	            if (getAndIncrement() != 0) {
68	                return;
69	            }
70	
71	            do {
72	                if (done) {
73	                    upstream.finish().whenComplete(this);
74	                    break;
75	                } else {
76	                    upstream.next().whenComplete(this);
77	                }
78	            } while (decrementAndGet() != 0);
79	        }
80	
81	        @Override
82	        public void accept(Object t, Throwable u) {
83	            if (done) {
84	                if (mainError != null || u != null) {
85	                    waiter.completeExceptionally(ExceptionHelper.unwrapAndCombine(mainError, u));
86	                } else {
87	                    waiter.complete(false);
88	                }
89	            } else {
90	                if (u != null) {
91	                    mainError = u;
92	                    done = true;
93	                } else
94	                if (!(Boolean)t) {
95	                    done = true;
96	                }
97	                drain();
98	            }
99	        }
100	
101	        @Override
102	        public @NonNull T current() {
103	            throw new NoSuchElementException();
104	        }
105	
106	        @Override
107	        public @NonNull CompletionStage<Void> finish() {
108	            return FINISHED;
109	        }
