25	public record StreamableTimer(long delay, @NonNull TimeUnit unit,
26	        @Nullable Scheduler scheduler,
27	        @Nullable ExecutorService executor) implements Streamable<Long> {
28	
29	    public StreamableTimer {
30	        if (scheduler == null && executor == null) {
31	            throw new IllegalArgumentException("scheduler and executor cannot be both null");
32	        }
33	    }
34	
35	    @Override
36	    public @NonNull Streamer<Long> stream(@NonNull StreamerCancellation cancellation) {
37	        var streamer = new TimerStreamer();
38	        cancellation.add(streamer);
39	        if (scheduler != null) {
40	            var d = scheduler.scheduleDirect(streamer, delay, unit);
41	            DisposableHelper.setOnce(streamer, d);
42	        } else
43	        if (executor instanceof ScheduledExecutorService se) {
44	            var f = se.schedule(streamer, delay, unit);
45	            DisposableHelper.setOnce(streamer, Disposable.fromFuture(f, true));
46	        } else {
47	            var f = executor.submit(() -> {
48	                try {
49	                    unit.sleep(delay);
50	                } catch (InterruptedException ex) {
51	                    streamer.interrupedSleep(ex);
52	                    return null;
53	                }
54	                streamer.run();
55	                return null;
56	            });
57	            DisposableHelper.setOnce(streamer, Disposable.fromFuture(f, true));
58	        }
59	        return streamer;
60	    }
61	
62	    static final class TimerStreamer extends AtomicReference<Disposable> implements Streamer<Long>,  Runnable, Disposable {
63	
64	        @Serial
65	        private static final long serialVersionUID = 1738554471573342053L;
66	
67	        int state;
68	
69	        final CompletableFuture<Boolean> waiter = new CompletableFuture<>();
70	
71	        @Override
72	        public void run() {
73	            waiter.complete(true);
74	        }
75	
76	        void interrupedSleep(InterruptedException ex) {
77	            if (!isDisposed()) {
78	                waiter.completeExceptionally(ex);
79	            }
80	        }
81	
82	        @Override
83	        public @NonNull CompletionStage<Boolean> next() {
84	            if (state == 0) {
85	                state = 1;
86	                return waiter;
87	            }
88	            return NEXT_FALSE;
89	        }
90	
91	        @Override
92	        public @NonNull Long current() {
93	            return 0L;
94	        }
95	
96	        @Override
97	        public @NonNull CompletionStage<Void> finish() {
98	            waiter.complete(false);
99	            DisposableHelper.dispose(this);
100	            return FINISHED;
101	        }
102	
103	        @Override
104	        public void dispose() {
105	            if (DisposableHelper.dispose(this)) {
106	                waiter.completeExceptionally(new CancellationException());
107	            }
108	        }
109	
110	        @Override
111	        public boolean isDisposed() {
112	            return get() == DisposableHelper.DISPOSED;
113	        }
114	    }
115	}
