26	public record StreamableIntervalRange(
27	        long start,
28	        long count,
29	        long initialDelay,
30	        long period,
31	        TimeUnit unit,
32	        Scheduler scheduler,
33	        ExecutorService executor
34	) implements Streamable<Long> {
