47	            DisposableHelper.setOnce(streamer, d);
48	        } else
49	        if (executor instanceof ScheduledExecutorService se) {
50	            var f = se.scheduleAtFixedRate(streamer, initialDelay, period, unit);
51	            DisposableHelper.setOnce(streamer, Disposable.fromFuture(f, true));
52	        } else {
53	            var s = Schedulers.from(executor, true);
54	            var d = s.schedulePeriodicallyDirect(streamer, initialDelay, period, unit);
