61	    static final class IntervalStreamer extends AtomicReference<Disposable>
62	    implements Streamer<Long>, Runnable, java.util.function.Function<Boolean, Boolean>, Disposable {
63	
64	        @Serial
65	        private static final long serialVersionUID = 197364198498939579L;
66	
67	        final long end;
68	
69	        long counterTask;
70	
71	        long counterLocal;
72	
73	        volatile Long available;
74	
75	        volatile Long current;
76	
77	        final AtomicReference<CompletableFuture<Boolean>> waiter;
78	
79	        IntervalStreamer(long start, long end) {
80	            this.counterTask = start;
81	            this.counterLocal = start;
82	            this.end = end;
83	            this.waiter = new AtomicReference<>();
84	        }
85	
86	        @Override
87	        public void run() {
88	            var c = counterTask++;
89	            available = c;
90	            if (c + 1 >= end) {
91	                DisposableHelper.dispose(this);
92	            }
93	            for (;;) {
94	                var cf = waiter.get();
95	                if (cf != null) {
96	                    cf.complete(true);
97	                    break;
98	                }
99	                cf = CompletableFuture.completedFuture(true);
100	                if (waiter.compareAndSet(null, cf)) {
101	                    break;
102	                }
103	            }
104	        }
105	
106	        @Override
107	        public @NonNull CompletionStage<Boolean> next() {
108	            waiter.set(null);
109	            for (;;) {
110	                if (counterLocal >= end) {
111	                    return NEXT_FALSE;
112	                }
113	                var c = current;
114	                var a = available;
115	                if (c == null && a != null) {
116	                    current = counterLocal++;
117	                    return NEXT_TRUE;
118	                }
119	                if (c != null && c < a) {
120	                    current = counterLocal++;
121	                    return NEXT_TRUE;
122	                }
123	                if (isDisposed()) {
124	                    return CompletableFuture.failedFuture(new CancellationException());
125	                }
126	                var cf = waiter.get();
127	                if (cf != null) {
128	                    waiter.set(null);
129	                    return cf.thenApply(this);
130	                }
131	                cf = new CompletableFuture<Boolean>();
132	                if (waiter.compareAndSet(null, cf)) {
133	                    return cf.thenApply(this);
134	                }
135	            }
136	        }
137	
138	        @Override
139	        public Boolean apply(Boolean t) {
140	            current = counterLocal++;
141	            return true;
142	        }
143	
144	        @Override
145	        public @NonNull Long current() {
146	            return current;
147	        }
148	
149	        @Override
150	        public @NonNull CompletionStage<Void> finish() {
151	            DisposableHelper.dispose(this);
152	            return FINISHED;
153	        }
154	
155	        @Override
156	        public void dispose() {
157	            DisposableHelper.dispose(this);
158	            var cf = waiter.getAndSet(null);
159	            if (cf != null) {
160	                cf.completeExceptionally(new CancellationException());
161	            }
162	        }
163	
164	        @Override
165	        public boolean isDisposed() {
166	            return get() == DisposableHelper.DISPOSED;
167	        }
168	    }
169	}
