23	public record StreamableTimeout<T>(
24	        Streamable<T> source,
25	        long timeout, TimeUnit unit, Scheduler scheduler,
26	        Streamable<T> fallback)
27	implements Streamable<T> {
28	
29	    @Override
30	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
31	        var worker = scheduler.createWorker();
32	        cancellation.add(worker);
33	        var dc = cancellation.derive();
34	        var streamer = new TimeoutStreamer<>(
35	                source.stream(dc), dc, cancellation,
36	                timeout, unit, worker, fallback);
37	        return streamer;
38	    }
39	
40	    static final class TimeoutStreamer<T> implements Streamer<T> {
41	
42	        final long timeout;
43	
44	        final TimeUnit unit;
45	
46	        final Worker worker;
47	
48	        final Streamable<T> fallback;
49	
50	        final Disposable mainDisposable;
51	
52	        final StreamerCancellation downstreamDisposable;
53	
54	        Streamer<T> mainStreamer;
55	
56	        Streamer<T> fallbackStreamer;
57	
58	        TimeoutStreamer(
59	                Streamer<T> mainStreamer, Disposable mainDisposable, StreamerCancellation downstreamDisposable,
60	                long timeout, TimeUnit unit, Worker worker, Streamable<T> fallback) {
61	            this.timeout = timeout;
62	            this.unit = unit;
63	            this.worker = worker;
64	            this.fallback = fallback;
65	            this.mainStreamer = mainStreamer;
66	            this.mainDisposable = mainDisposable;
67	            this.downstreamDisposable = downstreamDisposable;
68	        }
69	
70	        @Override
71	        public @NonNull CompletionStage<Boolean> next() {
72	            if (fallbackStreamer != null) {
73	                return fallbackStreamer.next();
74	            }
75	
76	            var mainNextResume = new CompletableFuture<Boolean>();
77	            var mainNext = mainStreamer.next();
78	            var mainNextTimeout = new CompletableFuture<Boolean>();
79	            Disposable d = worker.schedule(() -> mainNextTimeout.complete(false), timeout, unit);
80	            StreamableHelper.whenEither(mainNext, mainNextTimeout, winner -> {
81	                if (winner == 1) {
82	                    d.dispose();
83	                    StreamableHelper.forward(mainNext, mainNextResume);
84	                } else {
85	                    mainDisposable.dispose();
86	                    StreamableHelper.andThenSupply(
87	                            StreamableHelper.suppressValueAndCancel(mainNext, false),
88	                            () -> mainStreamer.finish()
89	                    ).whenComplete((_, e) -> {
90	                        if (e != null) {
91	                            mainNextResume.completeExceptionally(e);
92	                        } else {
93	                            fallbackStreamer = fallback.stream(downstreamDisposable);
94	                            StreamableHelper.forward(fallbackStreamer.next(), mainNextResume);
95	                        }
96	                    })
97	                    ;
98	                }
99	            });
100	            return mainNextResume;
101	        }
102	
103	        @Override
104	        public @NonNull T current() {
105	            if (fallbackStreamer != null) {
106	                return fallbackStreamer.current();
107	            }
108	            return mainStreamer.current();
109	        }
110	
111	        @Override
112	        public @NonNull CompletionStage<Void> finish() {
113	            worker.dispose();
114	            if (fallbackStreamer != null) {
115	                return fallbackStreamer.finish();
116	            }
117	            return mainStreamer.finish();
118	        }
119	    }
