93	            if (!once) {
94	                once = true;
95	
96	                if (upstream instanceof IndexableSource<?> isrc) {
97	                    long max = isrc.limit();
98	                    for (long index = 0; index < max; index++) {
99	                        if (cancellation.isDisposed()) {
100	                            return CompletableFuture.failedFuture(new CancellationException());
101	                        }
102	
103	                        try {
104	                            var value = (T)isrc.elementAt(index);
105	                            collector.accept(storage, value);
106	                        } catch (Throwable ex) {
107	                            Exceptions.throwIfFatal(ex);
108	                            return CompletableFuture.failedFuture(ex);
109	                        }
110	                    }
111	                    current = storage;
112	                    return NEXT_TRUE;
113	                } else
114	                if (upstream instanceof DeferredEnumerableSource<?> dsrc) {
115	                    StreamableHelper.whenComplete(dsrc.enumerableReady(), this::deferredEnumerate);
