191	                        }
192	                        state = upstreamNext.state();
193	                    }
194	
195	                    if (state == State.SUCCESS) {
196	                        if (upstreamNext.getNow((false))) {
197	                            try {
198	                                collector.accept(storage, upstream.current());
199	                            } catch (Throwable ex) {
200	                                Exceptions.throwIfFatal(ex);
