25	public record StreamableOnErrorResumeNext<T>(
26	        Streamable<T> source,
27	        Function<? super Throwable, ? extends Streamable<? extends T>> fallbackMapper
28	) implements Streamable<T> {
29	
30	    @Override
31	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
32	        return new OnErrorResumeNextStreamer<>(source.stream(cancellation), fallbackMapper, cancellation);
33	    }
34	
35	    static final class OnErrorResumeNextStreamer<T> implements Streamer<T> {
36	
37	        final StreamerCancellation downstreamDisposable;
38	
39	        final Function<? super Throwable, ? extends Streamable<? extends T>> fallbackMapper;
40	
41	        Streamer<T> mainStreamer;
42	
43	        Streamer<? extends T> fallbackStreamer;
44	
45	        public OnErrorResumeNextStreamer(Streamer<T> mainStreamer,
46	                Function<? super Throwable, ? extends Streamable<? extends T>> fallbackMapper,
47	                        StreamerCancellation downstreamDisposable) {
48	            this.mainStreamer = mainStreamer;
49	            this.fallbackMapper = fallbackMapper;
50	            this.downstreamDisposable = downstreamDisposable;
51	        }
52	
53	        @Override
54	        public @NonNull CompletionStage<Boolean> next() {
55	            if (fallbackStreamer != null) {
56	                return fallbackStreamer.next();
57	            }
58	            var cf = new CompletableFuture<Boolean>();
59	            mainStreamer.next().whenComplete((v, e) -> {
60	                if (e != null) {
61	                    var ms = mainStreamer;
62	                    mainStreamer = null;
63	                    ms.finish().whenComplete((_, e1) -> {
64	                        if (e1 != null) {
65	                            e.addSuppressed(e1);
66	                        }
67	                        try {
68	                            var fallback = Objects.requireNonNull(fallbackMapper.apply(e), "The fallbackMapper returned a null Streamable");
69	                            fallbackStreamer = fallback.stream(downstreamDisposable);
70	                            StreamableHelper.forward(fallbackStreamer.next(), cf);
71	                        } catch (Throwable ex) {
72	                            Exceptions.throwIfFatal(ex);
73	                            ex.addSuppressed(e);
74	                            cf.completeExceptionally(ex);
75	                        }
76	                    });
77	                } else {
78	                    cf.complete(v);
79	                }
80	            });
81	            return cf;
82	        }
83	
84	        @Override
85	        public @NonNull T current() {
86	            if (fallbackStreamer != null) {
87	                return fallbackStreamer.current();
88	            }
89	            return mainStreamer.current();
90	        }
91	
92	        @Override
93	        public @NonNull CompletionStage<Void> finish() {
94	            if (fallbackStreamer != null) {
95	                return fallbackStreamer.finish();
96	            }
97	            if (mainStreamer != null) {
98	                return mainStreamer.finish();
99	            }
100	            return FINISHED;
101	        }
102	    }
103	}
