30	public record StreamableSingleFlattenAs<T, U>(
31	        SingleSource<T> source,
32	        Function<? super T, @NonNull ? extends Iterable<? extends U>> mapper
33	) implements Streamable<U>, HasUpstreamSingleSource<T> {
34	
35	    @Override
36	    public @NonNull Streamer<@NonNull U> stream(@NonNull StreamerCancellation cancellation) {
37	        var observer = new FlattenAsSingleObserver<>(mapper, cancellation);
38	        cancellation.add(observer);
39	        source.subscribe(observer);
40	        return observer;
41	    }
42	
43	    static final class FlattenAsSingleObserver<T, U>
44	    extends AtomicInteger
45	    implements SingleObserver<T>, Streamer<U>, DisposableOnly,
46	            DeferredEnumerableSource<U> {
47	
48	        @Serial
49	        private static final long serialVersionUID = 796267562672678347L;
50	
51	        final StreamerCancellation cancellation;
52	
53	        final Function<? super T, @NonNull ? extends Iterable<? extends U>> mapper;
54	
55	        final SequentialDisposable upstream;
56	
57	        final CompletableFuture<Boolean> iteratorReady;
58	
59	        U current;
60	
61	        volatile Iterator<? extends U> currentIterator;
62	
63	        boolean deferredOnce;
64	
65	        FlattenAsSingleObserver(
66	                Function<? super T, @NonNull ? extends Iterable<? extends U>> mapper,
67	                StreamerCancellation cancellation) {
68	            this.cancellation = cancellation;
69	            this.mapper = mapper;
70	            this.iteratorReady = new CompletableFuture<>();
71	            this.upstream = new SequentialDisposable();
72	        }
73	
74	        @Override
75	        public @NonNull CompletionStage<Boolean> next() {
76	            var it = currentIterator;
77	            if (it == null) {
78	                return iteratorReady;
79	            }
80	            if (!deferredOnce) {
81	                deferredOnce = true;
82	                return NEXT_TRUE;
83	            }
84	            if (it.hasNext()) {
85	                current = it.next();
86	                return NEXT_TRUE;
87	            }
88	            return NEXT_FALSE;
89	        }
90	
91	        @Override
92	        public @NonNull U current() {
93	            return current;
94	        }
95	
96	        @Override
97	        public @NonNull CompletionStage<Void> finish() {
98	            currentIterator = null;
99	            DisposableHelper.dispose(upstream);
100	            return FINISHED;
101	        }
102	
103	        @Override
104	        public void dispose() {
105	            DisposableHelper.dispose(upstream);
106	            iteratorReady.completeExceptionally(new CancellationException());
107	        }
108	
109	        @Override
110	        public void onSubscribe(@NonNull Disposable d) {
111	            DisposableHelper.setOnce(upstream, d);
112	        }
113	
114	        @Override
115	        public void onSuccess(@NonNull T t) {
116	            try {
117	                var iterator = Objects.requireNonNull(mapper.apply(t), "The mapper returned a null Iterable").iterator();
118	                if (iterator.hasNext()) {
119	                    current = iterator.next();
120	                    this.currentIterator = iterator;
121	                    iteratorReady.complete(true);
122	                } else {
123	                    iteratorReady.complete(false);
124	                }
125	            } catch (Throwable ex) {
126	                Exceptions.throwIfFatal(ex);
127	                upstream.lazySet(DisposableHelper.DISPOSED);
128	                iteratorReady.completeExceptionally(ex);
129	                return;
130	            }
131	        }
132	
133	        @Override
134	        public void onError(@NonNull Throwable e) {
135	            upstream.lazySet(DisposableHelper.DISPOSED);
136	            iteratorReady.completeExceptionally(e);
137	        }
138	
139	        @Override
140	        public CompletionStage<Boolean> enumerableReady() {
141	            return iteratorReady;
142	        }
143	
144	        @Override
145	        public boolean nextSync() throws Throwable {
146	            // because onSuccess will pull out the first item
147	            if (!deferredOnce) {
148	                deferredOnce = true;
149	                return true;
150	            }
151	            if (currentIterator.hasNext()) {
152	                current = currentIterator.next();
153	                return true;
154	            }
155	            return false;
156	        }
157	    }
158	}
