31	
32	    final Streamable<T> source;
33	
34	    final T defaultItem;
35	
36	    public StreamableLastAsSingle(@Nullable Streamable<T> source, @Nullable T defaultItem) {
37	        this.source = source;
38	        this.defaultItem = defaultItem;
39	    }
40	
41	    @Override
42	    public @NonNull Streamable<@NonNull T> source() {
43	        return source;
44	    }
45	
46	    @Override
47	    protected void subscribeActual(@NonNull SingleObserver<? super @NonNull T> observer) {
48	        var cancellation = new CompositeDisposable();
49	        var drainer = new LastStreamer<>(observer, defaultItem, cancellation);
50	        observer.onSubscribe(drainer);
51	        drainer.upstream = source.stream(cancellation);
52	        drainer.drain();
53	    }
54	
55	    static final class LastStreamer<T>
56	    extends AtomicInteger
57	    implements BiConsumer<Object, Throwable>, DisposableOnly {
58	
59	        @Serial
60	        private static final long serialVersionUID = 2423155860070143815L;
61	
62	        final SingleObserver<? super T> downstream;
63	
64	        final DisposableStreamerCancellation cancellation;
65	
66	        final T defaultItem;
67	
68	        Streamer<T> upstream;
69	
70	        T current;
71	
72	        Throwable nextFailure;
73	
74	        volatile boolean done;
75	
76	        LastStreamer(
77	                SingleObserver<? super T> downstream,
78	                T defaultItem,
79	                DisposableStreamerCancellation cancellation) {
80	            this.downstream = downstream;
81	            this.defaultItem = defaultItem;
82	            this.cancellation = cancellation;
83	        }
84	
85	        void drain() {
86	            for (;;) {
87	                if (done) {
88	                    StreamableHelper.whenComplete(upstream.finish(), this);
89	                    return;
90	                } else {
91	                    var upstreamNext = upstream.next().toCompletableFuture();
92	
93	                    var state = upstreamNext.state();
94	
95	                    if (state == State.RUNNING) {
96	                        set(1);
97	                        upstreamNext.whenComplete(this);
98	                        if (compareAndSet(1, 0)) {
99	                            return;
100	                        }
101	                        state = upstreamNext.state();
102	                    }
103	
104	                    if (state == State.SUCCESS) {
105	                        if (upstreamNext.getNow(false)) {
106	                            current = upstream.current();
107	                        } else {
108	                            done = true;
109	                            StreamableHelper.whenComplete(upstream.finish(), this);
110	                            return;
111	                        }
112	                    } else {
113	                        nextFailure = upstreamNext.exceptionNow();
114	                        done = true;
115	                        StreamableHelper.whenComplete(upstream.finish(), this);
116	                        return;
117	                    }
118	                }
119	            }
120	        }
121	
122	        @Override
123	        public void accept(Object t, Throwable u) {
124	            if (done) {
125	                if (u != null || nextFailure != null) {
126	                    downstream.onError(ExceptionHelper.unwrapAndCombine(nextFailure, u));
127	                } else {
128	                    if (current == null) {
129	                        if (defaultItem != null) {
130	                            downstream.onSuccess(defaultItem);
131	                        } else {
132	                            downstream.onError(new NoSuchElementException());
133	                        }
134	                    } else {
135	                        downstream.onSuccess(current);
136	                    }
137	                }
138	            } else {
139	                if (!compareAndSet(1, 2)) {
140	                    if (u != null) {
141	                        nextFailure = u;
142	                        done = true;
143	                        drain();
144	                    } else {
145	                        if ((Boolean)t) {
146	                            current = upstream.current();
147	                        } else {
148	                            done = true;
149	                        }
150	                        drain();
151	                    }
152	                }
153	            }
154	        }
155	
156	        @Override
157	        public void dispose() {
158	            cancellation.dispose();
159	        }
160	    }
161	}
