38	    static final class ConcatIteratorStreamer<T> extends AtomicInteger
39	    implements Streamer<T>, BiConsumer<Boolean, Throwable> {
40	
41	        @Serial
42	        private static final long serialVersionUID = -9136569444189652718L;
43	
44	        final Iterator<? extends Streamable<? extends T>> iterator;
45	
46	        final StreamerCancellation cancellation;
47	
48	        DisposableStreamerCancellation currentCancellation;
49	
50	        volatile Streamer<? extends T> upstream;
51	
52	        CompletableFuture<Boolean> nextReady;
53	
54	        ConcatIteratorStreamer(Iterator<? extends Streamable<? extends T>> iterator,
55	                StreamerCancellation cancellation) {
56	            this.iterator = iterator;
57	            this.cancellation = cancellation;
58	        }
59	
60	        @Override
61	        public @NonNull CompletionStage<Boolean> next() {
62	            for (;;) {
63	                if (upstream == null) {
64	                    if (iterator.hasNext()) {
65	                        try {
66	                            var source = Objects.requireNonNull(iterator.next(), "The iterable returned a null Streamable");
67	                            currentCancellation = cancellation.derive();
68	                            upstream = source.stream(currentCancellation);
69	                        } catch (Throwable ex) {
70	                            Exceptions.throwIfFatal(ex);
71	                            return CompletableFuture.failedFuture(ex);
72	                        }
73	                    } else {
74	                        return NEXT_FALSE;
75	                    }
76	                }
77	                var stage = upstream.next();
78	                if (stage instanceof CompletableFuture<Boolean> cf) {
79	                    if (cf.state() == State.SUCCESS) {
80	                        if (cf.getNow(false)) {
81	                            return NEXT_TRUE;
82	                        } else {
83	                            var finishStage = upstream.finish();
84	                            if (finishStage instanceof CompletableFuture<Void> cff && cff.isDone()) {
85	                                upstream = null;
86	                                cancellation.delete(currentCancellation);
87	                                currentCancellation = null;
88	                                if (cff.isCompletedExceptionally()) {
89	                                    return CompletableFuture.failedFuture(cff.exceptionNow());
90	                                }
91	                                // will get the next source synchronously
92	                            } else {
93	                                nextReady = new CompletableFuture<Boolean>();
94	                                finishStage.whenComplete(this::whenFinishComplete);
95	                                return nextReady;
96	                            }
97	                        }
98	                    } else {
99	                        nextReady = new CompletableFuture<Boolean>();
100	                        stage.whenComplete(this);
101	                        return nextReady;
102	                    }
103	                } else {
104	                    nextReady = new CompletableFuture<Boolean>();
105	                    stage.whenComplete(this);
106	                    return nextReady;
107	                }
108	            }
109	        }
110	
111	        @Override
112	        public @NonNull T current() {
113	            return upstream.current();
114	        }
115	
116	        @Override
117	        public @NonNull CompletionStage<Void> finish() {
118	            var localUpstream = upstream;
119	            var localCurrentCancellation = currentCancellation;
120	            upstream = null;
121	            nextReady = null;
122	            currentCancellation = null;
123	            if (localUpstream != null) {
124	                cancellation.delete(localCurrentCancellation);
125	                return localUpstream.finish();
126	            }
127	            return FINISHED;
128	        }
129	
130	        void drain() {
131	            if (getAndIncrement() != 0) {
132	                return;
133	            }
134	
135	            do {
136	                if (upstream == null) {
137	                    if (iterator.hasNext()) {
138	                        currentCancellation = cancellation.derive();
139	                        var nextStreamable = iterator.next();
140	                        if (nextStreamable == null) {
141	                            nextReady.completeExceptionally(new NullPointerException("The iterator returned a null Streamable"));
142	                        } else {
143	                            upstream = nextStreamable.stream(currentCancellation);
144	                        }
145	                    } else {
146	                        nextReady.complete(false);
147	                    }
148	                }
149	                if (upstream != null) {
150	                    StreamableHelper.whenComplete(upstream.next(), this);
151	                }
152	            } while (decrementAndGet() != 0);
153	        }
154	
155	        @Override
156	        public void accept(Boolean v, Throwable e) {
157	            if (e != null) {
158	                nextReady.completeExceptionally(e);
159	            } else
160	            if (v)  {
161	                nextReady.complete(true);
162	            } else {
163	                cancellation.delete(currentCancellation);
164	                StreamableHelper.whenComplete(upstream.finish(), this::whenFinishComplete);
165	            }
166	        }
167	
168	        void whenFinishComplete(Void t, Throwable u) {
169	            if (u != null) {
170	                nextReady.completeExceptionally(u);
171	            } else {
172	                upstream = null;
173	                drain();
174	            }
175	        }
176	    }
177	}
