26	public record StreamableUsing<T, R>(
27	        Supplier<? extends R> resourceSupplier,
28	        Function<? super R, ? extends Streamable<? extends T>> resourceMapper,
29	        Consumer<? super R> resourceCleaner
30	)
31	implements Streamable<T> {
32	
33	    @Override
34	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
35	        R resource;
36	        Streamable<? extends T> source;
37	        try {
38	            resource = resourceSupplier.get();
39	        } catch (Throwable ex) {
40	            Exceptions.throwIfFatal(ex);
41	            return StreamableError.createFailed(ex);
42	        }
43	
44	        try {
45	            source = Objects.requireNonNull(resourceMapper.apply(resource), "The resourceMapper returned a null Streamable");
46	        } catch (Throwable ex) {
47	            Exceptions.throwIfFatal(ex);
48	            return new UsingStreamer<>(StreamableError.createFailed(ex), () -> resourceCleaner.accept(resource));
49	        }
50	
51	        return new UsingStreamer<>(source.stream(cancellation), () -> resourceCleaner.accept(resource));
52	    }
53	
54	    static final class UsingStreamer<T, R> implements Streamer<T> {
55	
56	        final Streamer<? extends T> upstream;
57	
58	        Action cleanup;
59	
60	        UsingStreamer(Streamer<? extends T> upstream, Action cleanup) {
61	            this.upstream = upstream;
62	            this.cleanup = cleanup;
63	        }
64	
65	        @Override
66	        public @NonNull CompletionStage<Boolean> next() {
67	            return upstream.next();
68	        }
69	
70	        @Override
71	        public @NonNull T current() {
72	            return upstream.current();
73	        }
74	
75	        @Override
76	        public @NonNull CompletionStage<Void> finish() {
77	            var cf = new CompletableFuture<Void>();
78	            upstream.finish().whenComplete((_, e) -> {
79	                try {
80	                    var c = cleanup;
81	                    cleanup = null;
82	                    c.run();
83	                } catch (Throwable ex) {
84	                    Exceptions.throwIfFatal(ex);
85	                    e = ExceptionHelper.unwrapAndCombine(e, ex);
86	                }
87	                if (e != null) {
88	                    cf.completeExceptionally(e);
89	                } else {
90	                    cf.complete(null);
91	                }
92	            });
93	            return cf;
94	        }
95	    }
96	}
