29	public record StreamableForEach() {
30	
31	    public static <T> CompletionStageDisposable<Void> forEach(
32	            @NonNull Streamable<T> me,
33	            @NonNull Consumer<? super T> consumer,
34	            @NonNull DisposableStreamerCancellation canceller,
35	            @NonNull ExecutorService executor) {
36	        var future = CompletableFuture.<Void>supplyAsync(() -> {
37	            Throwable finallyCrash = null;
38	            var str = me.stream(canceller);
39	            try {
40	                try {
41	                    while (!canceller.isDisposed()) {
42	                        if (str.awaitNext()) {
43	                            consumer.accept(Objects.requireNonNull(str.current(), "The upstream Streamable " + me.getClass() + " produced a null element!"));
44	                        } else {
45	                            break;
46	                        }
47	                    }
48	                } finally {
49	                    try {
50	                        str.awaitFinish();
51	                    } catch (Throwable ex) {
52	                        Exceptions.throwIfFatal(ex);
53	                        finallyCrash = ex;
54	                    }
55	                }
56	            } catch (Throwable crash) {
57	                Exceptions.throwIfFatal(crash);
58	                finallyCrash = ExceptionHelper.unwrapAndCombine(crash, finallyCrash);
59	            }
60	            if (finallyCrash != null) {
61	                throw ExceptionHelper.wrapOrThrow(finallyCrash);
62	            }
63	            return null;
64	        }, executor);
65	        canceller.add(Disposable.fromFuture(future));
66	        return new CompletionStageDisposable<>(future, canceller);
67	    }
68	
69	    public static <T> CompletionStageDisposable<Void> forEach(
70	            @NonNull Streamable<T> me,
71	            @NonNull BiConsumer<? super T, ? super Disposable> consumer,
72	            @NonNull DisposableStreamerCancellation canceller,
73	            @NonNull ExecutorService executor) {
74	        var future = CompletableFuture.<Void>supplyAsync(() -> {
75	            var str = me.stream(canceller);
76	            Throwable finallyCrash = null;
77	            try {
78	                try {
79	                    var stopper = Disposable.empty();
80	                    while (!canceller.isDisposed() && !stopper.isDisposed()) {
81	                        if (str.awaitNext()) {
82	                            var v = Objects.requireNonNull(str.current(), "The upstream Streamable " + me.getClass() + " produced a null element!");
83	                            consumer.accept(v, stopper);
84	                        } else {
85	                            break;
86	                        }
87	                    }
88	                } finally {
89	                    try {
90	                        str.awaitFinish();
91	                    } catch (Throwable ex) {
92	                        Exceptions.throwIfFatal(ex);
93	                        finallyCrash = ex;
94	                    }
95	                }
96	            } catch (final Throwable crash) {
97	                Exceptions.throwIfFatal(crash);
98	                finallyCrash = ExceptionHelper.unwrapAndCombine(crash, finallyCrash);
99	            }
100	            if (finallyCrash != null) {
101	                throw ExceptionHelper.wrapOrThrow(finallyCrash);
102	            }
103	            return null;
104	        }, executor);
105	        canceller.add(Disposable.fromFuture(future));
106	        return new CompletionStageDisposable<>(future, canceller);
107	    }
