109	    public static <T> CompletionStage<Void> forEach(
110	            Streamable<T> me, StreamSink<? super T> consumer, ExecutorService executor) {
111	        var cf = new CompletableFuture<Void>();
112	        CompletableFuture.runAsync(() -> {
113	            Throwable error = null;
114	            var cancellation = consumer.cancellation();
115	            var streamer = me.stream(cancellation);
116	            try {
117	                try {
118	                    while (!cancellation.isDisposed()) {
119	                        if (streamer.awaitNext()) {
120	                            Streamer.awaitBoolean(consumer.next(streamer.current()));
121	                        } else {
122	                            break;
123	                        }
124	                    }
125	                } finally {
126	                    try {
127	                        streamer.awaitFinish();
128	                    } catch (Throwable ex) {
129	                        Exceptions.throwIfFatal(ex);
130	                        error = ExceptionHelper.unwrap(ex);
131	                    }
132	                }
133	            } catch (Throwable crash) {
134	                Exceptions.throwIfFatal(crash);
135	                crash = ExceptionHelper.unwrap(crash);
136	                if (error != null) {
137	                    crash.addSuppressed(error);
138	                }
139	                error = crash;
140	            }
141	            try {
142	                Streamer.awaitVoid(consumer.finish(error));
143	            } catch (Throwable ex) {
144	                Exceptions.throwIfFatal(ex);
145	                if (error != null) {
146	                    ex.addSuppressed(error);
147	                }
148	                cf.completeExceptionally(ex);
149	                return;
150	            }
151	            cf.complete(null);
152	        }, executor);
153	        return cf;
154	    }
