27	public record StreamableIntercept<T>(
28	        Streamable<T> source,
29	        @NonNull BiFunction<? super StreamerCancellation, ? super Streamer<? extends T>, ? extends Streamer<? extends T>> onStream,
30	        @NonNull BiFunction<? super StreamerCancellation, ? super CompletionStage<Boolean>, ? extends CompletionStage<Boolean>> onNext,
31	        @NonNull Function<? super T, ? extends T> onCurrent,
32	        @NonNull BiFunction<? super StreamerCancellation, ? super CompletionStage<Void>, ? extends CompletionStage<Void>> onFinish
33	) implements Streamable<T>, HasUpstreamStreamableSource<T> {
34	
35	    @Override
36	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
37	        Streamer<? extends T> streamer;
38	        try {
39	            streamer = Objects.requireNonNull(onStream.apply(cancellation, source.stream(cancellation)), "onStream returned a null Streaner");
40	        } catch (Throwable ex) {
41	            Exceptions.throwIfFatal(ex);
42	            return StreamableError.createFailed(ex);
43	        }
44	        return new InterceptStreamer<>(streamer, onNext, onCurrent, onFinish, new AtomicReference<>(), new AtomicReference<>(cancellation));
45	    }
46	
47	    record InterceptStreamer<T>(
48	            @NonNull Streamer<? extends T> upstream,
49	            @NonNull BiFunction<? super StreamerCancellation, ? super CompletionStage<Boolean>, ? extends CompletionStage<Boolean>> onNext,
50	            @NonNull Function<? super T, ? extends T> onCurrent,
51	            @NonNull BiFunction<? super StreamerCancellation, ? super CompletionStage<Void>, ? extends CompletionStage<Void>> onFinish,
52	            @NonNull AtomicReference<T> currentRef,
53	            @NonNull AtomicReference<StreamerCancellation> cancellation
54	    ) implements Streamer<T> {
55	        @Override
56	        public @NonNull CompletionStage<Boolean> next() {
57	            CompletionStage<Boolean> result;
58	            try {
59	                result = Objects.requireNonNull(onNext.apply(cancellation.get(), upstream.next()), "The onNext returned a null CompletionStage");
60	            } catch (Throwable ex) {
61	                Exceptions.throwIfFatal(ex);
62	                return CompletableFuture.failedStage(ex);
63	            }
64	            return result.thenCompose(v -> {
65	                if (v) {
66	                    T t;
67	                    try {
68	                        t = Objects.requireNonNull(onCurrent.apply(upstream.current()), "The onCurrent returned a null value");
69	                    } catch (Throwable ex) {
70	                        Exceptions.throwIfFatal(ex);
71	                        currentRef.lazySet(null);
72	                        return CompletableFuture.failedStage(ex);
73	                    }
74	                    currentRef.lazySet(t);
75	                    return NEXT_TRUE;
76	                }
77	                currentRef.lazySet(null);
78	                return NEXT_FALSE;
79	            });
80	        }
81	
82	        @Override
83	        public @NonNull T current() {
84	            return currentRef.get();
85	        }
86	
87	        @Override
88	        public @NonNull CompletionStage<Void> finish() {
89	            CompletionStage<Void> result;
90	            try {
91	                result = Objects.requireNonNull(onFinish.apply(cancellation.get(), upstream.finish()), "onFinish returned a null CompletionStage");
92	            } catch (Throwable ex) {
93	                Exceptions.throwIfFatal(ex);
94	                result = CompletableFuture.failedStage(ex);
95	            }
96	            return result;
97	        }
98	    }
99	}
