59	        }
60	
61	        if (nextException != null || finishException != null) {
62	            throw ExceptionHelper.wrapOrThrow(ExceptionHelper.unwrapAndCombine(nextException, finishException));
63	        }
64	        if (result == null) {
65	            if (defaultItem != null) {
66	                return defaultItem;
67	            }
68	            throw new NoSuchElementException();
69	        }
70	        return result;
71	    }
