73	    /**
74	     * Consumes all upstream items and returns the very last or throws
75	     * a {@link NoSuchElementException} if {@code defaultItem} is also {@code null}.
76	     * @param <T> the element type
77	     * @param source the source sequence
78	     * @param defaultItem if not null, item to return if the source is empty
79	     * @param cancellation the external cancellation manager
80	     * @return the very last value
81	     * @throws RuntimeException if the source signals an unchecked exception
82	     * @throws CompletionException if the source signals a checked exception
83	     */
84	    public static <T> T blockingLast(Streamable<T> source, T defaultItem, StreamerCancellation cancellation) {
85	        var streamer = source.stream(cancellation);
86	        Throwable nextException = null;
87	        Throwable finishException = null;
88	        T result = null;
89	        try {
90	            while (streamer.awaitNext()) {
91	                result = streamer.current();
92	            }
93	        } catch (Throwable ex) {
94	            Exceptions.throwIfFatal(ex);
95	            nextException = ex;
96	        }
97	        try {
98	            streamer.awaitFinish();
99	        } catch (Throwable ex) {
100	            Exceptions.throwIfFatal(ex);
101	            finishException = ex;
102	        }
103	
104	        if (nextException != null || finishException != null) {
105	            throw ExceptionHelper.wrapOrThrow(ExceptionHelper.unwrapAndCombine(nextException, finishException));
106	        }
107	        if (result == null) {
108	            if (defaultItem != null) {
109	                return defaultItem;
110	            }
111	            throw new NoSuchElementException();
112	        }
113	        return result;
114	    }
115	}
