497	    /**
498	     * Emits elements from start up to start + count exclusive.
499	     * @param start the start element
500	     * @param count the number of elements to emit
501	     * @return the new {@code Streamable} instance
502	     * @throws IllegalArgumentException if {@code count} is negative
503	     */
504	    @CheckReturnValue
505	    @NonNull
506	    static Streamable<Integer> range(int start, int count) {
507	        if (count < 0) {
508	            throw new IllegalArgumentException("count >= 0 required but it was " + count);
509	        } else
510	        if (count == 0) {
511	            return empty();
512	        } else
513	        if (count == 1) {
514	            return just(start);
515	        } else
516	        if ((long)start + (count - 1) > Integer.MAX_VALUE) {
517	            throw new IllegalArgumentException("Integer overflow");
518	        }
519	        return RxJavaPlugins.onAssembly(new StreamableRange(start, count));
520	    }
521	
522	    /**
523	     * Emits elements from start up to start + count exclusive.
524	     * @param start the start element
525	     * @param count the number of elements to emit
526	     * @return the new {@code Streamable} instance
527	     * @throws IllegalArgumentException if {@code count} is negative
528	     */
529	    @CheckReturnValue
530	    @NonNull
531	    static Streamable<Long> rangeLong(long start, long count) {
532	        if (count < 0) {
533	            throw new IllegalArgumentException("count >= 0 required but it was " + count);
534	        }
535	
536	        if (count == 0) {
537	            return empty();
538	        }
539	
540	        if (count == 1) {
541	            return just(start);
542	        }
543	
544	        long end = start + (count - 1);
545	        if (start > 0 && end < 0) {
546	            throw new IllegalArgumentException("Overflow! start + count is bigger than Long.MAX_VALUE");
547	        }
548	        return RxJavaPlugins.onAssembly(new StreamableRangeLong(start, count));
549	    }

