31	public record StreamableZip<T>(
32	        Iterable<? extends Streamable<? extends T>> sources
33	) implements Streamable<List<T>> {
34	
35	    @Override
36	    public @NonNull Streamer<@NonNull List<T>> stream(@NonNull StreamerCancellation cancellation) {
37	        var dc = cancellation.derive();
38	
39	        var sourcesList = new ArrayList<Streamer<? extends T>>();
40	        int i = 0;
41	        for (var inner : sources) {
42	            if (inner == null) {
43	                return StreamableError.createFailed(new NullPointerException("The item at index " + i + " is null"));
44	            }
45	            sourcesList.add(inner.stream(dc));
46	            i++;
47	        }
48	
49	        if (sourcesList.isEmpty()) {
50	            return StreamableEmpty.createEmpty();
51	        }
52	        return new ZipStreamer<T>(sourcesList, dc);
53	    }
54	
55	    static final class ZipStreamer<T>
56	    implements Streamer<List<T>>, BiConsumer<Object, Throwable> {
57	
58	        final DisposableStreamerCancellation innerCancellation;
59	
60	        final List<? extends Streamer<? extends T>> streamers;
61	
62	        final AtomicInteger wip;
63	
64	        final AtomicInteger endWip;
65	
66	        final CompletableFuture<Void> finishReady;
67	
68	        final AtomicThrowable errors;
69	
70	        CompletableFuture<Boolean> nextReady;
71	
72	        Object[] working;
73	
74	        List<T> current;
75	
76	        final List<CompletionStage<Boolean>> nexts;
77	
78	        volatile boolean done;
79	
80	        ZipStreamer(List<? extends Streamer<? extends T>> streamers, DisposableStreamerCancellation innerCancellation) {
81	            this.streamers = streamers;
82	            this.innerCancellation = innerCancellation;
83	            this.wip = new AtomicInteger();
84	            this.finishReady = new CompletableFuture<>();
85	            this.errors = new AtomicThrowable();
86	            this.working =  new Object[streamers.size()];
87	            this.endWip = new AtomicInteger();
88	            nexts = new ArrayList<CompletionStage<Boolean>>(streamers.size());
89	        }
90	
91	        @Override
92	        public @NonNull CompletionStage<Boolean> next() {
93	            nextReady = new CompletableFuture<>();
94	            wip.set(streamers.size());
95	            Arrays.fill(working, null);
96	            nexts.clear();
97	            for (var innerStreamer : streamers) {
98	                var n = innerStreamer.next();
99	                nexts.add(n);
100	            }
101	            int i = 0;
102	            for (var stage : nexts) {
103	                var j = i++;
104	                stage.whenComplete((b, e) -> whenComplete(j, b, e));
105	            }
106	            return nextReady;
107	        }
108	
109	        @Override
110	        public @NonNull List<T> current() {
111	            return current;
112	        }
113	
114	        @Override
115	        public @NonNull CompletionStage<Void> finish() {
116	            working = null;
117	            current = null;
118	            nexts.clear();
119	            wip.set(streamers.size());
120	            errors.set(null);
121	            done = true;
122	            for (var innerStreamer : streamers) {
123	                innerStreamer.finish().whenComplete(this);
124	            }
125	            return finishReady;
126	        }
127	
128	        void whenComplete(int index, Boolean b, Throwable t) {
129	            if (t != null) {
130	                if (wip.getAndSet(0) != 0) {
131	                    errors.tryAddThrowableOrReport(t);
132	                    innerCancellation.dispose();
133	                    endWip.set(streamers.size());
134	                    int i = 0;
135	                    for (var next : nexts) {
136	                        if (index != i++) {
137	                            next.whenComplete(this);
138	                        } else {
139	                            accept(null, null);
140	                        }
141	                    }
142	                }
143	            } else
144	            if (b) {
145	                working[index] = streamers.get(index).current();
146	                if (wip.decrementAndGet() == 0) {
147	                    @SuppressWarnings("unchecked")
148	                    T[] result = (T[])working;
149	                    current = List.of(result);
150	                    nextReady.complete(true);
151	                }
152	            } else {
153	                if (wip.getAndSet(0) != 0) {
154	                    innerCancellation.dispose();
155	                    endWip.set(streamers.size());
156	                    int i = 0;
157	                    for (var next : nexts) {
158	                        if (index != i++) {
159	                            next.whenComplete(this);
160	                        } else {
161	                            accept(null, null);
162	                        }
163	                    }
164	                }
165	            }
166	        }
167	
168	        @Override
169	        public void accept(Object t, Throwable u) {
170	            if (done) {
171	                if (u != null) {
172	                    errors.tryAddThrowableOrReport(u);
173	                }
174	                if (wip.decrementAndGet() == 0) {
175	                    var err = errors.terminate();
176	                    if (err != null) {
177	                        finishReady.completeExceptionally(err);
178	                    } else {
179	                        finishReady.complete(null);
180	                    }
181	                }
182	            } else {
183	                if (u !=  null && !StreamableHelper.isCancellation(u)) {
184	                    errors.tryAddThrowableOrReport(u);
185	                }
186	                if (endWip.decrementAndGet() == 0) {
187	                    var err = errors.terminate();
188	                    if (err != null) {
189	                        nextReady.completeExceptionally(err);
190	                    } else {
191	                        nextReady.complete(false);
192	                    }
193	                }
194	            }
195	        }
196	    }
197	}
