26	/**
27	 * Represents the state for a Scheduler -&gt; ExecutorService interface.
28	 * @param scheduler the scheduler to use
29	 * @param workerStore hosts the worker state
30	 * @since 4.0.0
31	 */
32	public record SchedulerToExecutorService(@NonNull Scheduler scheduler,
33	        @NonNull AtomicReference<Worker> workerStore) implements ExecutorService {
34	
35	    @Override
36	    public void execute(Runnable command) {
37	        if (workerStore.get() instanceof Worker w) {
38	            w.schedule(command);
39	        } else {
40	            scheduler.scheduleDirect(command);
41	        }
42	    }
43	
44	    @Override
45	    public void shutdown() {
46	        if (workerStore.get() instanceof Worker w) {
47	            w.dispose();
48	        } else {
49	            // FIXME, generally we don't want to shut down RxJava schedulers like this!
50	            // scheduler.shutdown();
51	            var w = workerStore.getAndSet(Scheduler.Worker.SHUTDOWN);
52	            if (w != null) {
53	                w.dispose();
54	            }
55	        }
56	    }
57	
58	    @Override
59	    public List<Runnable> shutdownNow() {
60	        if (workerStore.get() instanceof Worker w) {
61	            w.dispose();
62	        } else {
63	            // FIXME, generally we don't want to shut down RxJava schedulers like this!
64	            // scheduler.shutdown();
65	            var w = workerStore.getAndSet(Scheduler.Worker.SHUTDOWN);
66	            if (w != null) {
67	                w.dispose();
68	            }
69	        }
70	        return List.of();
71	    }
