73	    @Override
74	    public boolean isShutdown() {
75	        var w = workerStore.get();
76	        return w != null && w.isDisposed();
77	    }
78	
79	    @Override
80	    public boolean isTerminated() {
81	        return isShutdown();
82	    }
83	
84	    @Override
85	    public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
86	        // FIXME no idea how to passively wait, not really applicable in Rx
87	        long timeoutNanos = unit.toNanos(timeout);
88	        if (isTerminated()) {
89	            return true;
90	        }
91	        if (timeoutNanos <= 0) {
92	            return false;
93	        }
94	
95	        long start = System.nanoTime();
96	        for (;;) {
97	            if (isTerminated()) {
98	                return true;
99	            }
100	
101	            long elapsed = System.nanoTime() - start;
102	            long remaining = timeoutNanos - elapsed;
103	            if (remaining <= 0) {
104	                return isTerminated();
105	            }
106	
107	            // There is no termination signal to await, so poll at a short interval.
108	            TimeUnit.NANOSECONDS.sleep(Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(1)));
109	        }
110	    }
