112	    @Override
113	    public <T> Future<T> submit(Callable<T> task) {
114	        return CompletableFuture.supplyAsync(() -> {
115	            try {
116	                return task.call();
117	            } catch (Throwable ex) {
118	                Exceptions.throwIfFatal(ex);
119	                throw Exceptions.propagate(ex);
120	            }
121	        }, this::execute);
122	    }
