124	    @Override
125	    public <T> Future<T> submit(Runnable task, T result) {
126	        return CompletableFuture.supplyAsync(() -> {
127	            try {
128	                task.run();
129	                return result;
130	            } catch (Throwable ex) {
131	                Exceptions.throwIfFatal(ex);
132	                throw Exceptions.propagate(ex);
133	            }
134	        }, this::execute);
