149	    @Override
150	    public <T> List<Future<T>> invokeAll(Collection<? extends Callable<T>> tasks) throws InterruptedException {
151	        var result = new ArrayList<Future<T>>();
152	        for (var task : tasks) {
153	            result.add(submit(task));
154	        }
155	        for (var f : result) {
156	            try {
157	                f.get();
158	            } catch (Throwable ex) {
159	                Exceptions.throwIfFatal(ex);
160	            }
161	        }
162	        return result;
163	    }
