165	    @Override
166	    public <T> List<Future<T>> invokeAll(Collection<? extends Callable<T>> tasks, long timeout, TimeUnit unit)
167	            throws InterruptedException {
168	        var result = new ArrayList<Future<T>>();
169	        var signal = new CompletableFuture<Void>();
170	        var signaller = new CompletionSignaller(signal);
171	        for (var task : tasks) {
172	            signaller.countUp();
173	            result.add(submit(() -> {
174	                try {
175	                    return task.call();
176	                } finally {
177	                    signaller.countDown();
178	                }
179	            }));
180	        }
181	
182	        signaller.countDown();
183	
184	        try {
185	            signal.get(timeout, unit);
186	            // make sure we have tasks really finished
187	            for (var f : result) {
188	                getException(f);
189	            }
190	        } catch (TimeoutException | ExecutionException ex) {
191	            for (var f : result) {
192	                f.cancel(true);
193	            }
194	        }
195	
196	        return result;
197	    }
