199	    @Override
200	    public <T> T invokeAny(Collection<? extends Callable<T>> tasks) throws InterruptedException, ExecutionException {
201	        if (tasks.isEmpty()) {
202	            throw new IllegalArgumentException("The tasks parameter should contain at least one callable!");
203	        }
204	
205	        var completionAll = new CompletableFuture<Void>();
206	        var signaller = new CompletionSignaller(completionAll);
207	        var completionPort = new CompletableFuture<CompletedIndexValue<T>>();
208	
209	        var result = new ArrayList<Future<T>>();
210	        var i = 0;
211	        for (var task : tasks) {
212	            signaller.countUp();
213	            var j = i;
214	            result.add(submit(() -> {
215	                try {
216	                    var v = task.call();
217	                    completionPort.complete(new CompletedIndexValue<>(j, v));
218	                    return v;
219	                } finally {
220	                    signaller.countDown();
221	                }
222	            }));
223	            i++;
224	        }
225	
226	        signaller.countDown();
227	
228	        var completionEither = new CompletableFuture<CompletableFuture<?>>();
229	
230	        completionPort.whenComplete((_, _) -> completionEither.complete(completionPort));
231	        completionAll.whenComplete((_, _) -> completionEither.complete(completionAll));
232	
233	        var resultCompletable = completionEither.get();
234	
235	        if (resultCompletable == completionPort) {
236	            var k = completionPort.getNow(null);
237	            for (int j = 0; j < result.size(); j++) {
238	                if (j != k.index()) {
239	                    result.get(j).cancel(true);
240	                }
241	            }
242	            return k.value();
243	        }
244	
245	        List<Throwable> errors = new ArrayList<>();
246	        for (var f : result) {
247	            errors.add(getException(f));
248	        }
249	        var composite = new CompositeException(errors);
250	        throw new ExecutionException(composite);
