283	        }
284	
285	        var completionAll = new CompletableFuture<Void>();
286	        var signaller = new CompletionSignaller(completionAll);
287	        var completionPort = new CompletableFuture<CompletedIndexValue<T>>();
288	
289	        var result = new ArrayList<Future<T>>();
290	        var i = 0;
291	        for (var task : tasks) {
292	            signaller.countUp();
293	            var j = i;
294	            result.add(submit(() -> {
295	                try {
296	                    var v = task.call();
297	                    completionPort.complete(new CompletedIndexValue<>(j, v));
298	                    return v;
299	                } finally {
300	                    signaller.countDown();
301	                }
302	            }));
303	            i++;
304	        }
305	
306	        signaller.countDown();
307	
308	        var completionEither = new CompletableFuture<CompletableFuture<?>>();
309	
310	        completionPort.whenComplete((_, _) -> completionEither.complete(completionPort));
311	        completionAll.whenComplete((_, _) -> completionEither.complete(completionAll));
312	
313	        var resultCompletable = completionEither.get(timeout, unit);
314	
315	        if (resultCompletable == completionPort) {
316	            var k = completionPort.getNow(null);
317	            for (int j = 0; j < result.size(); j++) {
318	                if (j != k.index()) {
319	                    result.get(j).cancel(true);
320	                }
321	            }
322	            return k.value();
323	        }
324	
325	        List<Throwable> errors = new ArrayList<>();
326	        for (var f : result) {
327	            errors.add(getException(f));
328	        }
329	        var composite = new CompositeException(errors);
330	        throw new ExecutionException(composite);
331	    }
