27	/**
28	 * Signals the various {@link #next(Object)} and {@link #finish(Throwable)} events to one or more
29	 * downstream {@link Streamer}s.
30	 * <p>
31	 * This is equivalent with to a {@link PublishProcessor} or {@link MulticastProcessor}, adapted to
32	 * the {@link Streamable} world.
33	 * @param <T> the element type of the input and output values
34	 * @since 4.0.0
35	 */
36	public final class DispatchStreamProcessor<T> implements StreamProcessor<T, T> {
37	
38	    static final DispatchStreamer<?>[] TERMINATED = new DispatchStreamer<?>[0];
39	
40	    static final DispatchStreamer<?>[] EMPTY = new DispatchStreamer<?>[0];
41	
42	    final AtomicReference<DispatchStreamer<?>[]> streamers = new AtomicReference<>(EMPTY);
43	
44	    volatile Throwable terminalEvent;
45	
46	    @Override
47	    public @NonNull Streamer<@NonNull T> stream(@NonNull StreamerCancellation cancellation) {
48	        var result = new DispatchStreamer<T>(this);
49	        if (add(result)) {
50	            // Register with cancellation after a successful add. If cancellation
51	            // already disposed the streamer (or dispose races with add), remove again
52	            // because the first remove may have observed the pre-add array.
53	            cancellation.add(result);
54	            if (result.isDisposed()) {
55	                remove(result);
56	            }
57	            return result;
58	        }
59	        var t = terminalEvent;
60	        if (t != ExceptionHelper.TERMINATED) {
61	            return StreamableError.createFailed(t);
62	        }
63	        return StreamableEmpty.createEmpty();
64	    }
65	
66	    @Override
67	    public CompletionStage<Boolean> next(@NonNull T item) {
68	        @SuppressWarnings("unchecked")
69	        var currentStreamers = (DispatchStreamer<T>[])streamers.get();
70	        if (currentStreamers.length == 0) {
71	            return Streamer.NEXT_FALSE;
72	        }
73	        List<CompletionStage<Boolean>> waiters = new ArrayList<>();
74	        for (var str : currentStreamers) {
75	            waiters.add(str.send(item));
76	        }
77	        return StreamableHelper.awaitAllBoolean(waiters);
78	    }
79	
80	    @Override
81	    public CompletionStage<Void> finish(@Nullable Throwable throwable) {
82	        terminalEvent = throwable == null ? ExceptionHelper.TERMINATED : throwable;
83	        @SuppressWarnings("unchecked")
84	        var currentStreamers = (DispatchStreamer<T>[])streamers.getAndSet(TERMINATED);
85	        if (currentStreamers.length == 0) {
86	            return Streamer.FINISHED;
87	        }
88	        List<CompletionStage<Void>> waiters = new ArrayList<>();
89	        for (var str : currentStreamers) {
90	            waiters.add(str.error(throwable));
91	        }
92	        return StreamableHelper.awaitAllVoid(waiters);
93	    }
94	
95	    boolean add(DispatchStreamer<T> streamer) {
96	        for (;;) {
97	            var currentStreamers = streamers.get();
98	            if (currentStreamers == TERMINATED) {
99	                return false;
100	            }
101	            var length = currentStreamers.length;
102	            var nextStreamers = Arrays.copyOf(currentStreamers, length + 1);
103	            nextStreamers[length] = streamer;
104	            if (streamers.compareAndSet(currentStreamers, nextStreamers)) {
105	                return true;
106	            }
107	        }
108	    }
109	
110	    boolean remove(DispatchStreamer<T> streamer) {
111	        for (;;) {
112	            var currentStreamers = streamers.get();
113	            var length = currentStreamers.length;
114	            if (length == 0) {
115	                return false;
116	            }
117	            int j = -1;
118	            for (var i = 0; i < length; i++) {
119	                if (currentStreamers[i] == streamer) {
120	                    j = i;
121	                    break;
122	                }
123	            }
124	            if (j < 0) {
125	                return false;
126	            }
127	            DispatchStreamer<?>[] nextStreamers;
128	            if (length == 1) {
129	                nextStreamers = EMPTY;
130	            } else {
131	                nextStreamers = new DispatchStreamer<?>[length - 1];
132	                System.arraycopy(currentStreamers, 0, nextStreamers, 0, j);
133	                System.arraycopy(currentStreamers, j + 1, nextStreamers, j, length - j - 1);
134	            }
135	            if (streamers.compareAndSet(currentStreamers, nextStreamers)) {
136	                return true;
137	            }
138	        }
139	    }
140	
141	    @Override
142	    public boolean hasStreamers() {
143	        return streamers.get().length != 0;
144	    }
145	
146	    @Override
147	    public int streamerCount() {
148	        return streamers.get().length;
149	    }
150	
151	    @Override
152	    public boolean hasComplete() {
153	        return terminalEvent == ExceptionHelper.TERMINATED;
154	    }
155	
156	    @Override
157	    public boolean hasThrowable() {
158	        var te = terminalEvent;
159	        return te != null && te != ExceptionHelper.TERMINATED;
160	    }
161	
162	    @Override
163	    public @Nullable Throwable getThrowable() {
164	        var te = terminalEvent;
165	        if (te != null && te != ExceptionHelper.TERMINATED) {
166	            return te;
167	        }
168	        return null;
169	    }
170	
171	    static final class DispatchStreamer<T>
172	    implements Streamer<T>, Function<Boolean, Boolean>, Disposable {
173	
174	        final DispatchStreamProcessor<T> parent;
175	
176	        final StageResumable<Boolean> consumerReady;
177	
178	        final StageResumable<Boolean> producerReady;
179	
180	        T current;
181	
182	        T incoming;
183	
184	        volatile boolean disposed;
185	
186	        DispatchStreamer(DispatchStreamProcessor<T> parent) {
187	            this.parent = parent;
188	            consumerReady = new StageResumable<>();
189	            producerReady = new StageResumable<>();
190	        }
191	
192	        @Override
193	        public @NonNull CompletionStage<Boolean> next() {
194	            // I O.println("DispatchStreamer.next()");
195	            consumerReady.ready().complete(true);
196	            return producerReady.await().thenApply(this);
197	        }
198	
199	        @Override
200	        public Boolean apply(Boolean t) {
201	            // I O.println("DispatchStreamer.apply(" + incoming + ")");
202	            current = incoming;
203	            incoming = null;
204	            return t;
205	        }
206	
207	        @Override
208	        public @NonNull T current() {
209	            // I O.println("DispatchStreamer.current(" + current + ")");
210	            return current;
211	        }
212	
213	        @Override
214	        public @NonNull CompletionStage<Void> finish() {
215	            // I O.println("DispatchStreamer.finish()");
216	            // new Exception().printStackTrace(System.out);
217	            current = null;
218	            parent.remove(this);
219	            consumerReady.ready().complete(false);
220	            return FINISHED;
221	        }
222	
223	        CompletionStage<Boolean> send(T item) {
224	            // I O.println("DispatchStreamer.send(" + item + ") // <-----------------------");
225	            return consumerReady.await().thenApply(v -> {
226	                // I O.println("DSP: consumerReady.await().thenAccept(" + v + ", " + item + ")");
227	                incoming = item;
228	                producerReady.ready().complete(true);
229	                return v;
230	            });
231	        }
232	
233	        CompletionStage<Void> error(Throwable t) {
234	            // I O.println("DispatchStreamer.error(" + t + ") // <-------------------------");
235	            return consumerReady.await().thenAccept(_ -> {
236	                if (t != null) {
237	                    producerReady.ready().completeExceptionally(t);
238	                } else {
239	                    producerReady.ready().complete(false);
240	                }
241	            });
242	        }
243	
244	        @Override
245	        public void dispose() {
246	            // I O.println("DispatchStreamer.dispose()");
247	            disposed = true;
248	            if (parent.remove(this)) {
249	                var ce = new CancellationException();
250	                producerReady.ready().completeExceptionally(ce);
251	            }
252	        }
253	
254	        @Override
255	        public boolean isDisposed() {
256	            return disposed;
257	        }
258	    }
259	}
