449	     * @return the new {@code Streamable} instance
450	     * @throws NullPointerException if {@code unit} or {@code executor} is {@code null}
451	     * @throws IllegalArgumentException if {@code count} is negative
452	     */
453	    @SchedulerSupport(SchedulerSupport.CUSTOM)
454	    @CheckReturnValue
455	    @NonNull
456	    static Streamable<Long> intervalRange(long start, long count,
457	            long initialDelay, long period, TimeUnit unit, ExecutorService executor) {
458	        Objects.requireNonNull(unit, "unit is null");
459	        Objects.requireNonNull(executor, "executor is null");
460	        if (count < 0) {
461	            throw new IllegalArgumentException("count >= 0 required but it was " + count);
462	        }
463	
464	        long end = start + (count - 1);
465	        if (start > 0 && end < 0) {
466	            throw new IllegalArgumentException("Overflow! start + count is bigger than Long.MAX_VALUE");
467	        }
468	        return RxJavaPlugins.onAssembly(new StreamableIntervalRange(start, count, initialDelay, period, unit, null, executor));
469	    }

