package io.reactivex.rxjava4.internal.operators.streamable;

import java.io.Serial;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

import io.reactivex.rxjava4.annotations.NonNull;
import io.reactivex.rxjava4.core.*;
import io.reactivex.rxjava4.disposables.*;
import io.reactivex.rxjava4.internal.disposables.DisposableHelper;
import io.reactivex.rxjava4.internal.fuseable.HasUpstreamMaybeSource;

public record StreamableFromMaybe<T>(MaybeSource<T> source)
implements Streamable<T>, HasUpstreamMaybeSource<T> {

    @Override
    public @NonNull Streamer<T> stream(@NonNull StreamerCancellation cancellation) {
        var streamer = new MaybeStreamer<T>(cancellation);
        cancellation.add(streamer);
        source.subscribe(streamer);
        return streamer;
    }

    static final class MaybeStreamer<T>
    extends AtomicReference<Disposable>
    implements Streamer<T>, MaybeObserver<T>, Disposable {

        @Serial
        private static final long serialVersionUID = -4580514428263096178L;

        final StreamerCancellation cancellation;

        final CompletableFuture<Boolean> waiter = new CompletableFuture<>();

        int stage;

        volatile T current;

        MaybeStreamer(StreamerCancellation cancellation) {
            this.cancellation = cancellation;
        }

        @Override
        public void onSubscribe(@NonNull Disposable d) {
            DisposableHelper.setOnce(this, d);
        }

        @Override
        public void onSuccess(@NonNull T t) {
            current = t;
            waiter.complete(true);
        }

        @Override
        public void onComplete() {
            waiter.complete(false);
        }

        @Override
        public void onError(@NonNull Throwable e) {
            waiter.completeExceptionally(e);
        }

        @Override
        public @NonNull CompletionStage<Boolean> next() {
            if (stage++ == 0) {
                return waiter;
            }
            return NEXT_FALSE;
        }

        @Override
        public @NonNull T current() {
            return current;
        }

        @Override
        public @NonNull CompletionStage<Void> finish() {
            current = null;
            cancellation.delete(this);
            return FINISHED;
        }

        @Override
        public void dispose() {
            DisposableHelper.dispose(this);
            waiter.completeExceptionally(new CancellationException());
        }

        @Override
        public boolean isDisposed() {
            return get() == DisposableHelper.DISPOSED;
        }
    }
}

    /**
     * Adds a disposable to this container or disposes it if the
     * container has been disposed.
     * @param d the disposable to add, not null
     * @return true if successful, false if this container has been disposed
     */
    boolean add(@NonNull Disposable d);

    /**
     * Removes and disposes the given disposable if it is part of this
     * container.
     * @param d the disposable to remove and dispose, not null
     * @return true if the operation was successful
     */
    boolean remove(@NonNull Disposable d);

    /**
     * Removes but does not dispose the given disposable if it is part of this
     * container.
     * @param d the disposable to remove, not null
     * @return true if the operation was successful
     */
    boolean delete(@NonNull Disposable d);

    /**
     * Create a derived sub-cancellation management interface that can get disposed
     * by this cancellation management object but disposing the sub-cancellation
     * manager does not dispose this current {@code StreamerCancellation} instance..
     * @return the derived sub-cancellation management object
     */
    @NonNull
    DisposableStreamerCancellation derive();

}

