    @Test
    public void asyncNoDuplicateFirstItem() throws Throwable {
        // Source completes asynchronously (after subscription), exercising the plain
        // next()/current() protocol where the first item arrives via iteratorReady.
        var ss = SingleSubject.<Integer>create();

        var to = ss.flattenAsStreamable(v -> List.of(v * 10, v * 20, v * 30))
        .test();

        to.awaitOnSubscribe(1, TimeUnit.SECONDS);
        awaitCondition(true, () -> ss.hasObservers(), 1000);

        ss.onSuccess(1);

        to.awaitDone(5, TimeUnit.SECONDS)
        .assertResult(10, 20, 30);
    }
}

